function navigation(p){const item=id=>id==='users'&&actor?.role!=='admin'?'':`<button class="nav-item ${page===id?'active':''}" data-action="nav" data-id="${id}" ${page===id?'aria-current="page"':''} ${!p&&!['overview','maintenance','users'].includes(id)?'disabled':''}><span>${icons[id]}</span>${pages[id]}</button>`;return item('overview')+navigationGroups.map(([id,label,items])=>`<div class="nav-group" data-group="${id}"><h2 class="nav-group-title">${label}</h2>${items.map(item).join('')}</div>`).join('');}
function setNavigation(open){document.body.classList.toggle('navigation-open',open);$('#menu-toggle')?.setAttribute('aria-expanded',String(open));const shell=$('.main-shell');if(shell)shell.inert=open;if(open)$('#sidebar-close')?.focus();else $('#menu-toggle')?.focus();}
document.addEventListener('keydown',event=>{if(!document.body.classList.contains('navigation-open'))return;if(event.key==='Escape'){event.preventDefault();setNavigation(false);}else if(event.key==='Tab'){const nodes=[...$('#main-navigation').querySelectorAll('a[href],button:not(:disabled)')].filter(el=>el.getClientRects().length),first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
