async function load(){if(mode==='demo'){const raw=localStorage.getItem('solucao-sobrados-v1-demo');state=raw?validate(JSON.parse(raw)):demo();}else{const data=await accountApi('/me');actor=data.actor;setAccountContext(actor);organizationName=data.organizationName;boardLinks=data.boardLinks;state=data.financial||empty();}if(!projects().some(p=>p.id===selected))selected=projects()[0]?.id||'';}
async function boot(){try{if(location.hash.startsWith('#convite=')){state=empty();actor=null;setAccountContext(null);disposeDiary?.();disposeReminders?.();disposePhoto?.();disposeMaintenance?.();disposeUsers?.();loginScreen($('#app'),async()=>{mode='online';await boot();});return;}await load();const access=readDiaryLink();if(access){disposeDiary=mountSharedDiary($('#app'),access);}else render();}catch(error){state=empty();actor=null;setAccountContext(null);disposeDiary?.();disposeReminders?.();disposePhoto?.();disposeMaintenance?.();disposeUsers?.();document.body.classList.remove('navigation-open');loginScreen($('#app'),async()=>{mode='online';await boot();});if(error.status!==401)toast(error.message,true);}}
function maintenanceApi(action,payload){return accountApi('/maintenance',action==='command'?payload:undefined);}
function accountBoard(p){return boardLinks.find(b=>b.projectId===p.id);}
async function connectAccountBoard(p,legacy){const data=await accountApi('/boards',{projectId:p.id,...(legacy?{legacy}:{})});boardLinks=boardLinks.filter(b=>b.projectId!==p.id).concat(data);return data;}
function migrationForm(){if(actor.role!=='admin')throw new Error('Somente o administrador pode importar a base.');const raw=localStorage.getItem('solucao-sobrados-v1-workspace');if(!raw)throw new Error('Nenhuma base antiga encontrada neste navegador. Use Restaurar para importar um arquivo.');const financial=validate(JSON.parse(raw)),revision=state.revision;dialog('Transferir minha base para a conta',`<p class="callout wide">${financial.projects.length} empreendimento(s) serão enviados para ${esc(organizationName)}, com custos, vendas, recebimentos e anexos locais. Isso substituirá a base financeira desta conta. Os documentos e fotos online precisam ser vinculados separadamente pelo administrador.</p><p class="fine wide">Uma cópia de segurança será baixada. Após confirmar a transferência, a base antiga deste navegador será removida para não ficar acessível fora do login neste computador.</p>`+field('confirm','Digite TRANSFERIR para confirmar','','text','required'),async f=>{if(f.get('confirm')!=='TRANSFERIR')throw new Error('Digite TRANSFERIR para confirmar.');download('backup-antes-da-conta-'+today()+'.json',raw);await accountApi('/restore',{revision,financial});localStorage.removeItem('solucao-sobrados-v1-workspace');await load();render();toast('Base transferida para a conta.');},'Transferir para minha conta');}

