async function save(type,payload){let out;if(mode==='demo'){out=command(state,type,payload);localStorage.setItem('solucao-sobrados-v1-demo',JSON.stringify(out.state));}else out=await accountApi('/command',{type,payload,revision:state.revision});state=out.state;if(type==='contractor.save')page='contractors';if(['sale.save','unit.commercial','sale.cancel'].includes(type))page='sales';if(type==='project.create'||type==='project.restore'){selected=out.result.id;page='project';}if(type==='project.trash'){selected=projects()[0]?.id||'';page='overview';}render();toast(mode==='demo'?'Exemplo salvo neste navegador.':'Registro salvo na conta.');return out.result;}

function download(name,content,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
const tag=(text,tone='')=>`<span class="tag ${tone}">${esc(text)}</span>`;
const btn=(action,label,id='',kind='')=>`<button class="btn ${kind}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
