  const p=current();document.title=`Solução Sobrados · ${pages[page]}`;
  $('#app').innerHTML=`<aside class="sidebar" id="main-navigation" aria-label="Navegação principal"><button class="sidebar-close" id="sidebar-close" aria-label="Fechar menu" data-action="menu-close">×</button><a class="logo" href="#" data-action="overview"><span class="logo-mark">${icons.project}</span><span>SOLUÇÃO<strong>SOBRADOS</strong></span></a><div class="sidebar-project"><span>EMPREENDIMENTO</span><strong>${esc(p?.name||'Sua próxima obra')}</strong><small>${p?p.units.length+' casas · '+fmt(sum(p.units,'area')/100)+' m²':'Comece pelo cadastro'}</small></div><nav aria-label="Módulos">${navigation(p)}</nav><div class="sidebar-bottom"><strong>Central de gestão</strong><p>Da primeira medida ao resultado.</p></div></aside><button id="nav-backdrop" class="nav-backdrop" aria-label="Fechar navegação" data-action="menu-close" tabindex="-1"></button><div class="main-shell" data-area="${pageArea(page)}"><header class="topbar"><button class="menu-toggle btn" id="menu-toggle" aria-controls="main-navigation" aria-expanded="false" data-action="menu-open">☰ Menu</button><div class="project-identity"><span id="project-photo" class="project-photo" title="Empreendimento sem foto definida">⌂</span><div class="project-selector"><span>Empreendimento</span><select id="project-select" aria-label="Selecionar empreendimento">${p?projects().map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join(''):'<option>Crie seu primeiro empreendimento</option>'}</select></div></div><div class="top-actions"><span class="account-status">${esc(actor?.name)} · ${esc(roleLabels[actor?.role])}</span>${btn('logout','Sair')}${btn('refresh','↻ Atualizar')}${btn('backup','↓ Backup financeiro')}${btn('project-trash-list','Lixeira ('+(state.projects.length-projects().length)+')')}${actor?.role==='admin'?btn('import','Restaurar'):''}${btn('workspace',mode==='demo'?'Voltar à minha conta':'Ver exemplos')}<span class="avatar" title="Testes locais">SS</span></div></header><div class="test-strip"><span class="dot"></span>${mode==='demo'?'EXEMPLOS FICTÍCIOS · alterações ficam apenas neste navegador':'CONTA ONLINE · '+esc(organizationName)+' · acesso individual por cargo'}</div>${page==='overview'&&p?'':'<div id="reminder-summary" class="reminder-summary"></div>'}<main id="main" tabindex="-1">${!p&&!['maintenance','users'].includes(page)?title('COMECE PELO EMPREENDIMENTO','Uma obra organizada começa aqui.','Cadastre o terreno, as unidades e o formato de contratação. Depois, acompanhe cada custo até a entrega.',btn('project-new','+ Novo empreendimento','','primary'))+emptyView('Seu próximo sobrado, com os números em dia.','Nenhuma obra cadastrada nesta base. Os exemplos continuam disponíveis em “Ver exemplos”.'):({maintenance:()=>'<div id="maintenance-section"></div>',users:()=>'<div id="users-section"></div>',overview:overview,project:projectPage,costs:costsPage,contractors:contractorsPage,sales:salesPage,receipts:receiptsPage,stages:stagesPage,documents:()=>'<div id="diary-section"></div>',diary:()=>'<div id="diary-section"></div>',reminders:()=>'<div id="diary-section"></div>',profit:profitPage,market:marketPage,history:historyPage}[page])(p)}</main><footer class="app-footer"><span>Solução Sobrados</span><span>Independente do Moove ON · ${projects().length} empreendimentos nesta base</span></footer></div><datalist id="categories">${CATEGORIES.map(x=>`<option value="${x}">`).join('')}</datalist><datalist id="neighborhoods">${NEIGHBORHOODS.map(x=>`<option value="${x}">`).join('')}</datalist>`;
  if(page==='maintenance'){if(mode==='demo')$('#maintenance-section').innerHTML='<section class="card"><h1>Manutenção</h1><p>Volte à sua conta para acompanhar os chamados.</p></section>';else disposeMaintenance=mountMaintenance({container:$('#maintenance-section'),api:maintenanceApi,actor,projects:[],users:[]});}
