  $('#project-select').onchange=e=>{selected=e.target.value;costFilter={stage:'',kind:'',search:'',unit:''};marketFilter={condition:'new',includeUnknownZone:false,unitId:'',bedrooms:null,areaMin:null,areaMax:null};render();};
