function overview(p){const t=totals(p),sales=salesTotals(p),progress=physicalProgress(p),contracts=p.expenses.filter(e=>!e.cancelled&&isContractor(e)),contracted=sum(contracts,'total'),settled=sum(contracts,paid),over=t.stages.filter(st=>st.budget>0&&st.contracted>st.budget),due=sales.rows.flatMap(s=>s.installments.filter(i=>i.due<today()&&received(s,i.id)<i.cents));
 return title('VISÃO GERAL','Sua obra, de ponta a ponta.',`${esc(p.name)} · ${p.units.length} casas · ${fmt(t.area)} m² de área privativa`,p.status==='closed'?tag('Obra encerrada','blue'):btn('expense-quick','+ Registrar um gasto','','primary'))+
 `<div class="management-metrics">${metric('Custos contratados',money(t.contracted),money(t.paid)+' pagos · '+money(t.pending)+' a pagar','finance')}${metric('Vendas contratadas',money(sales.sold),sales.rows.length+' de '+p.units.length+' casas vendidas','commercial')}${metric('Valor já recebido',money(sales.received),money(sales.pending)+' a receber das vendas','finance')}</div>
 <div class="management-grid"><section class="card management-progress"><div class="section-head"><div><span class="eyebrow">OBRA</span><h2>Como está a construção</h2></div>${btn('nav','Ver etapas →','stages')}</div><div class="physical-total"><strong>${progress.percent===null?'Não informado':fmt(progress.percent)+'%'}</strong><span>da obra concluída</span></div><div class="progress" role="progressbar" aria-label="Avanço total da obra" ${progress.percent===null?'':`aria-valuenow="${progress.percent}"`} aria-valuemin="0" aria-valuemax="100"><i style="width:${progress.percent??0}%"></i></div>${progress.stages.slice(0,4).map(st=>`<div class="management-phase"><span>${esc(st.name)}</span><div class="progress" role="progressbar" aria-label="${esc(st.name)}" aria-valuenow="${st.progress}" aria-valuemin="0" aria-valuemax="100"><i style="width:${st.progress}%"></i></div><b>${fmt(st.progress)}%</b></div>`).join('')}<p class="fine">${progress.completed} de ${progress.count} etapas concluídas. Média das etapas aplicáveis, com o mesmo peso por fase. Atualização manual, independente dos pagamentos.</p></section>
 <section class="card management-actions"><div class="section-head"><div><span class="eyebrow">SUA ROTINA</span><h2>Próximas ações</h2></div>${btn('nav','Agenda →','reminders')}</div><div id="reminder-summary" class="reminder-summary"><p class="fine">Consulte os prazos e lembretes da obra na Agenda.</p></div><div class="attention"><span class="attention-icon sand">!</span><div><strong>${due.length} parcela(s) de venda vencida(s)</strong><p>${due.length?'Confira os recebimentos e os saldos em aberto.':'Nenhuma parcela de venda vencida com saldo.'}</p>${btn('nav','Ver recebimentos','receipts')}</div></div><div class="attention"><span class="attention-icon blue">↗</span><div><strong>${over.length} etapa(s) acima do orçamento informado</strong><p>Confira os custos e atualize a previsão da obra.</p>${btn('nav','Conferir custos','costs')}</div></div></section>
 <section class="card management-units"><div class="section-head"><div><span class="eyebrow">COMERCIAL</span><h2>Cada casa, uma negociação</h2></div>${btn('nav','Ver vendas →','sales')}</div><div class="management-houses">${p.units.map(u=>{const sale=activeSale(p,u.id);return `<button class="management-house ${sale?'sold':''}" data-action="${sale?'sale-detail':p.status==='closed'?'nav':'unit-commercial'}" data-id="${sale?sale.id:p.status==='closed'?'sales':u.id}" aria-label="${esc(u.name)}, ${sale?'vendida':'disponível'}"><span>${icons.project}</span><strong>${esc(u.name)}</strong><small>${sale?'Vendida':'Disponível'}</small><small>${fmt(u.area/100)} m²</small></button>`;}).join('')}</div><p class="fine">${sales.rows.length} vendidas · ${sales.available} disponíveis. Valor contratado e recebimento são acompanhados separadamente.</p></section>
 <section class="card management-contractor"><div class="section-head"><div><span class="eyebrow">FINANCEIRO</span><h2>Controle do empreiteiro</h2></div>${btn('nav','Abrir →','contractors')}</div>${contracts.length?`<h3>${contracts.length===1?esc(contracts[0].supplier||'Nome não informado'):contracts.length+' contratos de empreiteiro'}</h3><p>${contracts.length===1?esc(contracts[0].description):contracts.slice(0,3).map(e=>esc(e.supplier||'Nome não informado')).join(' · ')}</p><div class="management-contract-totals"><div><span>Contratado</span><strong>${money(contracted)}</strong></div><div><span>Já pago</span><strong>${money(settled)}</strong></div><div><span>A pagar</span><strong>${money(contracted-settled)}</strong></div></div><p class="fine">Valores destes contratos já incluídos nos custos gerais.</p>`:'<p>Nenhum contrato de empreiteiro cadastrado.</p><p class="fine">Informe o preço combinado e os serviços para acompanhar os vales e o saldo.</p>'+btn('nav','Cadastrar ou conferir contratos','contractors')}</section></div>
 <section class="card section-gap management-projections"><div class="section-head"><div><span class="eyebrow">PLANEJAMENTO</span><h2>Viabilidade do empreendimento</h2></div>${btn('nav','Ver viabilidade →','profit')}</div><div class="metrics">${metric('Custo final previsto',money(t.forecast),'Etapas + excedentes + reserva')}${metric('Lucro previsto',money(t.profit),'Após custos e despesas de venda')}${metric('Margem prevista',pct(t.margin),'Meta: '+fmt(p.targetBps/100)+'% da receita')}${metric('Custo completo previsto / m²',money(t.costPerSqm),fmt(t.area)+' m² de área privativa')}</div>${projectionNotice(p)}<div class="actions section-gap">${btn('nav','Ver custo por casa','project')}${btn('report','Relatório completo')}${btn('project-new','+ Empreendimento')}</div></section>`;
}
function projectPage(p){const t=totals(p);return title('CADASTRO DO EMPREENDIMENTO',esc(p.name),`${esc(p.address||'Endereço não informado')} · ${esc(p.neighborhood)} · ${esc(p.zone)}`,btn('project-edit','Editar empreendimento')+btn('project-trash','Excluir empreendimento',p.id,'danger')+btn('project-new','+ Novo empreendimento','','primary'))+
  projectionNotice(p)+`<div class="project-facts card"><div><span>Formato</span><strong>${p.type==='condominium'?'Sobrados em condomínio':'Sobrado individual'}</strong></div><div><span>Início</span><strong>${brDate(p.start)}</strong></div><div><span>Tipologia</span><strong>${[...new Set(p.units.map(u=>u.bedrooms??p.bedrooms))].sort((a,b)=>a-b).join(' / ')} dormitórios</strong></div><div><span>Unidades / área</span><strong>${p.units.length} / ${fmt(t.area)} m²</strong></div><div><span>Rateio padrão</span><strong>${p.allocation==='area'?'Por área privativa':'Igual por unidade'}</strong></div></div>
  <section class="card"><div class="section-head"><div><h2>As unidades do empreendimento</h2><p>Custos diretos + participação nos custos comuns + previsão restante.</p></div>${p.status!=='closed'?btn('unit-add','+ Adicionar unidade'):''}${tag('Valores de venda estimados','blue')}</div><div class="units-grid">${t.units.map(u=>`<article class="unit-card"><div class="unit-top"><span class="house-icon">⌂</span>${tag(fmt(u.area/100)+' m²')}</div><h3>${esc(u.name)}</h3><p>${u.bedrooms??p.bedrooms} dormitórios${u.bathrooms!=null?' · '+u.bathrooms+' banheiros':''}${u.parking!=null?' · '+u.parking+' vagas':''}</p>${u.notes?'<p class="fine">'+esc(u.notes)+'</p>':''}<dl><div><dt>Custo contratado</dt><dd>${money(u.contracted)}</dd></div><div><dt>Custo final previsto</dt><dd>${money(u.forecast)}</dd></div><div><dt>Pago alocado</dt><dd>${money(u.paid)}</dd></div><div><dt>${u.sold?'Venda contratada':'Venda estimada'}</dt><dd>${money(u.sale)}</dd></div><div class="unit-result"><dt>Lucro / margem</dt><dd>${money(u.profit)}<small>${pct(u.margin)}</small></dd></div></dl>${p.status!=='closed'?btn('unit-edit','Editar unidade',u.id):''}</article>`).join('')}</div><p class="fine">Alterar a área muda apenas os próximos rateios e a previsão não contratada. Custos existentes mantêm o rateio gravado; edite cada lançamento se precisar redistribuí-lo.</p></section><section class="card section-gap"><h2>Observações do empreendimento</h2><p>${esc(p.notes||'Nenhuma observação registrada.')}</p><div class="callout">Zona 1, 2 e 3 são classificações de localização informadas pela equipe para pesquisa de mercado. O cadastro não valida zoneamento urbanístico nem substitui consulta à Prefeitura.</div><div class="actions section-gap">${p.status==='closed'?btn('project-reopen','Reabrir obra com justificativa'):btn('project-close','Encerrar obra e conferir custos','','danger')}${btn('report','Relatório de fechamento')}</div></section>`;}
function filteredCosts(p){return p.expenses.filter(e=>!e.cancelled&&(!costFilter.stage||e.stageId===costFilter.stage)&&(!costFilter.kind||e.kind===costFilter.kind)&&(!costFilter.unit||(e.allocation[costFilter.unit]||0)>0)&&(!costFilter.search||[e.description,e.category,e.supplier].join(' ').toLowerCase().includes(costFilter.search.toLowerCase())));}
function costTable(p,rows,actions=true){return `<div class="table-scroll"><table><thead><tr><th>Lançamento / categoria</th><th>Etapa / destino</th><th>Quantidade</th><th>Contratado</th><th>Pago</th><th>Saldo</th>${actions?'<th>Ações</th>':''}</tr></thead><tbody>${rows.map(e=>`<tr><td><strong>${esc(e.description)}</strong><small>${esc(e.category)} · ${esc(e.supplier||'Sem fornecedor')}</small>${e.extraToContract?tag('Adicional fora da empreitada','sand'):''}</td><td>${esc(p.stages.find(st=>st.id===e.stageId).name)}<small>${e.mode==='direct'?esc(p.units.find(u=>u.id===e.unitId)?.name||'Unidade'):e.mode==='area'?'Comum · por área':'Comum · igualitário'}</small></td><td>${fmt(e.qty/1000)} ${esc(e.uom)}<small>${money(e.unitCents)} / ${esc(e.uom)}</small></td><td class="numeric">${money(e.total)}</td><td class="numeric">${money(paid(e))}</td><td class="numeric">${tag(money(e.total-paid(e)),paid(e)===e.total?'green':'sand')}</td>${actions?`<td><div class="row-actions">${btn('expense-detail','Ver',e.id)}${e.total>paid(e)&&p.status!=='closed'?btn('payment','Pagar',e.id):''}</div></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function constructionPanel(p){
  const t=constructionTotals(p);
  const review=(rows,excluded)=>rows.length?`<div class="table-scroll"><table><thead><tr><th>Lançamento / categoria</th><th>Pago</th><th>Critério</th><th></th></tr></thead><tbody>${rows.map(({expense:e,reason})=>`<tr><td><strong>${esc(e.description)}</strong><small>${esc(e.category)}</small></td><td class="numeric">${money(paid(e))}</td><td>${esc(reason||(e.constructionScope==='included'?'Inclusão informada':'Construção pela categoria'))}</td><td>${p.status!=='closed'?btn('construction-classify','Classificar',e.id):''}</td></tr>`).join('')}</tbody></table></div>`:`<p>Nenhum lançamento ${excluded?'excluído':'incluído'}.</p>`;
  return `<section class="card quick-catalog" aria-label="Construção por casa e por m²"><div class="section-head"><div><span class="eyebrow">CONSTRUÇÃO POR METRAGEM</span><h2>Quanto custou construir cada casa?</h2><p>Valor já pago. Terreno, comissões e impostos são excluídos automaticamente; confira as classificações abaixo.</p></div></div>
  <div class="metrics">${metric('Construção já paga',money(t.paid),'Base do cálculo por área','teal')}${metric('Construção por m²',money(t.costPerSqm),'Construção paga ÷ área privativa')}${metric('Área total das casas',fmt(t.area)+' m²',p.units.length+' unidades cadastradas')}${metric('Pagos fora da construção',money(t.excludedPaid),'Confira as exclusões abaixo','sand')}</div>
  <p class="callout">${money(t.paid)} ÷ ${fmt(t.area)} m² = <strong>${money(t.costPerSqm)}/m²</strong>. O custo de cada casa é proporcional à sua metragem. O cálculo usa a precisão integral e distribui os centavos para fechar o total.</p>
  <div class="table-scroll"><table class="construction-units"><thead><tr><th>Casa</th><th>Metragem</th><th>Custo da construção</th></tr></thead><tbody>${t.units.map(u=>`<tr><td><strong>${esc(u.name)}</strong></td><td>${fmt(u.area/100)} m²</td><td class="numeric">${money(u.constructionPaid)}</td></tr>`).join('')}</tbody><tfoot><tr><td><strong>Total</strong></td><td>${fmt(t.area)} m²</td><td class="numeric"><strong>${money(t.paid)}</strong></td></tr></tfoot></table></div>
  <p class="fine">Este quadro considera toda a obra, independentemente dos filtros abaixo. É uma distribuição analítica por área atual: os rateios diretos e comuns dos lançamentos permanecem no detalhamento e em Empreendimento. Não inclui orçamento futuro nem reserva. Construção contratada: ${money(t.contracted)}; ainda a pagar: ${money(t.pending)}.</p>
  <details class="quick-details"><summary>Conferir exclusões (${t.excluded.length} lançamentos)</summary><p class="fine">Automático: natureza Aquisição, categoria Terreno, comissões, impostos, tributos, IPTU, ITBI, ISS e INSS/FGTS. Projetos, água e luz continuam incluídos. Use Classificar para ajustar um lançamento.</p>${review(t.excluded,true)}</details>
  <details class="quick-details section-gap"><summary>Conferir construção incluída (${t.included.length} lançamentos)</summary>${review(t.included,false)}</details></section>`;
}
function constructionForm(p,e){dialog('Classificação no custo da construção',`<div class="callout wide"><strong>${esc(e.description)}</strong><br>${esc(e.category)} · Pago ${money(paid(e))}<br>Altera somente a participação neste cálculo por m²; preserva valores, pagamentos e rateios registrados.</div>`+select('constructionScope','Participação na construção',Object.entries(CONSTRUCTION_SCOPES),e.constructionScope||'auto'),f=>save('expense.construction',{projectId:p.id,id:e.id,constructionScope:f.get('constructionScope')}),'Salvar classificação');}
function costsPage(p){const rows=filteredCosts(p);return title('PLANILHA DE CUSTOS','Cada gasto, no lugar certo.','Materiais, mão de obra, terreno e imprevistos. Pagamentos parciais preservam o saldo de cada compromisso.',btn('export-costs','↓ Exportar CSV')+btn('expense-quick','+ Gasto rápido','','primary')+btn('expense-new','Lançamento detalhado'))+
  `${constructionPanel(p)}${p.status!=='closed'?quickCatalog():''}<section class="card"><form id="cost-filters" class="filters">${field('search','Buscar custo / fornecedor',costFilter.search)}${select('stage','Etapa',[['','Todas as etapas'],...p.stages.map(st=>[st.id,st.name])],costFilter.stage)}${select('kind','Natureza',[['','Todas'],...Object.entries(KINDS)],costFilter.kind)}${select('unit','Destino',[['','Todas as unidades'],...p.units.map(u=>[u.id,u.name])],costFilter.unit)}<button class="btn">Filtrar</button></form><div class="totals-line"><span>${rows.length} lançamentos</span><strong>Contratado ${money(sum(rows,'total'))}</strong><span>Pago ${money(sum(rows,paid))}</span><span>Saldo ${money(sum(rows,e=>e.total-paid(e)))}</span></div>${rows.length?costTable(p,rows):emptyView('Nenhum lançamento neste filtro.','Os filtros são combinados. Gastos importados podem estar em Histórico importado; selecione Todas as etapas para conferir a natureza ou a descrição.',btn('cost-filter-reset','Limpar filtros'))}${costFilter.unit?'<p class="callout">O filtro por unidade mostra os lançamentos que a atendem, com o valor integral do documento. A participação da unidade aparece em Empreendimento e no detalhamento.</p>':''}</section>${stageBudgets(p)}<details class="quick-details section-gap"><summary>Materiais: compra e consumo</summary>${materialCosts(p)}</details>`;}
function progressPanel(p,link=false){const progress=physicalProgress(p);return `<section class="card physical-summary section-gap"><div class="section-head"><div><span class="eyebrow">ANDAMENTO DA OBRA</span><h2>Quanto da obra está concluído?</h2></div>${link?btn('nav','Atualizar etapas →','stages'):''}</div><div class="physical-total"><strong>${progress.percent===null?'Não informado':fmt(progress.percent)+'%'}</strong><span>${progress.completed} de ${progress.count} etapas concluídas</span></div><div class="progress" role="progressbar" aria-label="Avanço total da obra" ${progress.percent===null?'':`aria-valuenow="${progress.percent}"`} aria-valuemin="0" aria-valuemax="100"><i style="width:${progress.percent??0}%"></i></div><p class="fine">${progress.count?'Média dos percentuais das etapas aplicáveis, com o mesmo peso para cada etapa.':'Marque as etapas aplicáveis para acompanhar o avanço.'} Etapas não aplicáveis ficam fora da conta. Atualização manual, independente dos custos e pagamentos.</p></section>`;}
function stagesPage(p){const progress=physicalProgress(p),inactive=p.stages.filter(st=>!st.unassigned&&!isProgressStage(st)),closed=p.status==='closed';const cards=rows=>`<div class="units-grid">${rows.map(st=>`<article class="unit-card phase-card"><h3>${esc(st.name)}</h3><strong class="phase-percent">${isProgressStage(st)?st.progress+'%':'Não se aplica'}</strong>${isProgressStage(st)?`<div class="progress"><i style="width:${st.progress}%"></i></div><p class="fine">${st.progress===100?'Etapa concluída':st.progress===0?'Não iniciada':'Em andamento'}</p>`:'<p class="fine">Fora do cálculo do avanço total.</p>'}${closed?'':btn('stage-edit',isProgressStage(st)?'Atualizar percentual':'Incluir / ajustar',st.id)}</article>`).join('')}</div>`;return title('AVANÇO FÍSICO','Etapas da obra','Informe quanto de cada fase foi concluído.',closed?'':btn('stage-new','+ Etapa personalizada','','primary'))+progressPanel(p)+`<section class="card section-gap"><h2>Etapas aplicáveis</h2>${progress.count?cards(progress.stages):emptyView('Nenhuma etapa selecionada.','Inclua as fases aplicáveis abaixo ou cadastre uma etapa personalizada.')}</section>${inactive.length?`<details class="quick-details section-gap"><summary>Etapas fora do avanço (${inactive.length})</summary><p class="fine">Você pode incluir uma etapa quando ela fizer parte do acompanhamento desta obra.</p>${cards(inactive)}</details>`:''}`;}
function stageBudgets(p){const t=totals(p);return `<details class="quick-details section-gap"><summary>Orçamentos por etapa</summary><div class="table-scroll"><table><thead><tr><th>Etapa</th><th>Orçado</th><th>Contratado</th><th>Pago</th><th>Previsão final</th><th></th></tr></thead><tbody>${t.stages.map(st=>`<tr><td>${esc(st.name)}</td><td>${money(st.budget)}</td><td>${money(st.contracted)}</td><td>${money(st.paid)}</td><td>${money(st.forecast)}</td><td>${p.status==='closed'?'':btn('stage-budget','Ajustar orçamento',st.id)}</td></tr>`).join('')}</tbody></table></div><p class="fine">A previsão financeira considera o maior valor entre orçamento e contratado por etapa, mais a reserva. O orçamento não altera o avanço físico.</p></details>`;}
function materialCosts(p){const materials=p.expenses.filter(e=>!e.cancelled&&e.kind==='material'&&(tracksQuantity(e)||e.uses.length)),amountOnly=p.expenses.filter(e=>!e.cancelled&&e.kind==='material'&&!tracksQuantity(e));return `<section class="card section-gap"><div class="section-head"><div><h2>Materiais: compra e consumo</h2><p>Consumo é uma informação de uso; não cria outro custo nem altera o rateio financeiro da compra.</p></div></div>${amountOnly.length?`<div class="callout"><strong>${amountOnly.length} gasto(s) de material informado(s) somente por valor.</strong> Eles já estão nos custos. Para controlar consumo, edite o mesmo lançamento e informe quantidade física e medida, preservando o valor total. Não crie outra compra. Registros antigos de uso em verba permanecem no histórico abaixo.</div><div class="actions section-gap">${amountOnly.map(e=>btn(p.status==='closed'||e.uses.length?'expense-detail':'expense-edit',esc(e.description)+(p.status==='closed'||e.uses.length?' · Ver custo':' · Informar quantidade'),e.id)).join('')}</div>`:''}${materials.length?`<div class="table-scroll"><table><thead><tr><th>Material</th><th>Comprado</th><th>Utilizado</th><th>Disponível</th><th>Onde foi usado</th><th></th></tr></thead><tbody>${materials.map(e=>`<tr><td><strong>${esc(e.description)}</strong><small>${esc(e.uom)} · ${money(e.unitCents)} por medida</small></td><td>${fmt(e.qty/1000)}</td><td>${fmt(used(e)/1000)}</td><td>${fmt((e.qty-used(e))/1000)}</td><td>${e.uses.map(u=>`<small>${esc(p.stages.find(st=>st.id===u.stageId).name)} · ${fmt(u.qty/1000)} ${esc(e.uom)}${u.unitId?' · '+esc(p.units.find(x=>x.id===u.unitId).name):''}</small>`).join('')||'Sem consumo registrado'}</td><td>${!tracksQuantity(e)?tag('Histórico sem medida física','sand'):p.status!=='closed'?btn('material-use','Registrar uso',e.id):''}</td></tr>`).join('')}</tbody></table></div>`:emptyView('Nenhum material com quantidade física.','Informe sacos, quilos, metros ou outra medida no lançamento detalhado para acompanhar o consumo.')}</section>`;}

function profitPage(p){const t=totals(p);return title('VIABILIDADE DO EMPREENDIMENTO','A obra precisa caber no resultado.','Cenários de venda para entender sua margem antes de tomar a próxima decisão.',btn('project-edit','Ajustar premissas')+btn('report','Relatório completo','','primary'))+
  projectionNotice(p)+`<div class="metrics">${metric('Vendas contratadas + previstas',money(t.revenue),p.units.length+' unidades')}${metric('Custo final previsto',money(t.forecast),'Inclui '+money(t.reserve)+' de reserva','teal')}${metric('Lucro previsto',money(t.profit),'Receita − custos − despesas de venda',t.profit>=0?'green':'rose')}${metric('Margem sobre a venda',pct(t.margin),'Retorno sobre custo total: '+pct(t.returnOnCost),'sand')}</div><div class="dashboard-grid"><section class="card"><h2>A conta aberta, sem surpresas</h2><div class="waterfall"><div><span>Vendas contratadas + previstas</span><strong>${money(t.revenue)}</strong></div><div><span>Custos previstos por etapa (inclui comissões lançadas)</span><strong>− ${money(t.base)}</strong></div><div><span>Reserva · ${p.status==='closed'?'não aplicada à obra encerrada':fmt(p.reserveBps/100)+'% sobre o custo base'}</span><strong>− ${money(t.reserve)}</strong></div><div><span>Despesas de venda ainda previstas · referência de ${fmt(p.sellingBps/100)}%</span><strong>− ${money(t.selling)}</strong></div><div class="total"><span>Lucro previsto</span><strong>${money(t.profit)}</strong></div></div><p class="fine">Comissões registradas nas vendas já entram nos custos e são descontadas da previsão de despesas de venda, evitando duplicidade. As taxas são premissas informadas pela equipe, não alíquotas oficiais. Tributos e outros custos precisam estar lançados. Venda estimada não representa contrato assinado nem recebimento.</p></section><section class="card"><span class="eyebrow">SEUS PONTOS DE REFERÊNCIA</span><h2>Por quanto precisa vender?</h2><div class="target"><span>Para cobrir custos e despesas de venda</span><strong>${money(t.breakEven)}</strong><small>${money(Math.ceil(t.breakEven/p.units.length))} por unidade, média</small></div><div class="target"><span>Para atingir ${fmt(p.targetBps/100)}% de margem</span><strong>${money(t.targetRevenue)}</strong><small>${money(Math.ceil(t.targetRevenue/p.units.length))} por unidade, média</small></div>${btn('nav','Comparar com anúncios da região →','market')}</section></div><section class="card section-gap"><div class="section-head"><h2>Se o valor de venda mudar…</h2><span class="muted">Vendas já contratadas são mantidas; cenários alteram somente as casas disponíveis</span></div><div class="scenario-grid">${[[-1000,'Conservador','Disponíveis: venda 10% menor'],[0,'Planejado','Seu preço atual'],[1000,'Otimista','Disponíveis: venda 10% maior']].map(([bps,label,help])=>{const x=scenario(p,bps);return `<article class="scenario ${bps===0?'selected':''}"><span>${label}</span><small>${help}</small><strong>${money(x.profit)}</strong><span>lucro previsto</span>${tag(pct(x.margin)+' de margem',x.profit>=0?'green':'rose')}<p>Receita ${money(x.revenue)}</p></article>`;}).join('')}</div></section>`;}
function marketPage(p){const criteria=resolveMarketCriteria(p,marketFilter),unit=p.units.find(u=>u.id===criteria.unitId),m=market(state,p,criteria),searchUrl=buildMarketSearchUrl(p,criteria);
 return title('REFERÊNCIAS DE MERCADO','Seu preço, com contexto.','Compare anúncios semelhantes. O preço pedido ajuda no planejamento, mas não confirma o valor de uma venda.',`<a class="btn" href="${esc(searchUrl)}" target="_blank" rel="noopener noreferrer">Buscar anúncios ↗</a>`+btn('comparable-new','+ Registrar referência','','primary'))+
 `<section class="card"><form id="market-filters" class="filters">${select('unitId','Unidade de referência',p.units.map(u=>[u.id,`${u.name} · ${fmt(u.area/100)} m²`]),unit.id)}${select('bedrooms','Dormitórios',[['all','Todos'],...Array.from({length:10},(_,i)=>[String(i+1),String(i+1)])],String(criteria.bedrooms))}${number('areaMin','Área mínima (m²)',val(criteria.areaMin),.01)}${number('areaMax','Área máxima (m²)',val(criteria.areaMax),.01)}${select('condition','Condição do imóvel',[['new','Novo'],['used','Usado / reformado'],['all','Todas as condições']],criteria.condition)}${check('includeUnknownZone','Incluir anúncios com zona não informada',marketFilter.includeUnknownZone)}</form><p id="market-filter-error" class="form-error" role="alert"></p><p class="fine">Recorte: ${esc(p.neighborhood)} · ${esc(p.zone)} · ${criteria.bedrooms==='all'?'todos os dormitórios':criteria.bedrooms+' dormitórios'} · ${p.type==='condominium'?'condomínio':'individual'} · de ${fmt(criteria.areaMin/100)} a ${fmt(criteria.areaMax/100)} m² · consulta até 90 dias. Bairro e zona são declarados; sem geolocalização automática.</p><div class="metrics three">${metric('Referências compatíveis',String(m.rows.length),'De '+m.examined.length+' anúncios cadastrados')}${metric('Mediana por m²',m.median?money(m.median):'Amostra insuficiente','Mínimo de 3 referências compatíveis','teal')}${metric('Indicação para '+fmt(unit.area/100)+' m²',m.estimate?money(m.estimate):'Complete a pesquisa',m.estimate?'Faixa observada: '+money(m.min)+' a '+money(m.max):'Nenhum preço será aplicado automaticamente','sand')}</div><div class="callout">Ao alterar dormitórios, faixa de área ou condição, a comparação e o link Buscar anúncios usam os novos critérios. A busca abre a pesquisa na web. Registre os anúncios conferidos com link e data; esta versão não coleta nem atualiza portais automaticamente. A mediana é uma referência simples de preços anunciados, sem laudo de avaliação. Confira duplicidades do mesmo imóvel entre imobiliárias.</div></section>
 <section class="section-gap"><div class="section-head"><h2>Referências e fontes</h2><span class="muted">Cada anúncio informa se entra na comparação</span></div><div class="market-grid">${m.examined.map(c=>`<article class="card market-card"><div class="section-head">${tag(c.reasons.length?'Fora do recorte':'Incluído',c.reasons.length?'sand':'green')}<span class="muted">${brDate(c.date)}</span></div><h3>${esc(c.title)}</h3><strong class="asking-price">${money(c.price)}</strong><p>${fmt(c.area/100)} m² · ${c.bedrooms} dormitórios · ${esc(c.zone)}</p><p class="muted">${esc(c.source)} · ${money(Math.round(c.rate))}/m²</p><p>${esc(c.notes)}</p>${c.reasons.length?`<p class="exclusion">${esc(c.reasons.join(' · '))}</p>`:''}<div class="actions"><a class="btn" href="${esc(c.url)}" target="_blank" rel="noopener noreferrer">Abrir fonte ↗</a>${btn('comparable-edit','Conferir / editar',c.id)}</div></article>`).join('')||emptyView('Comece sua pesquisa.','Busque sobrados com características parecidas e registre as referências verificadas.')}</div></section>`;
}
function historyPage(p){const rows=history(state,years.a,years.b),allYears=[...new Set(projects().flatMap(p=>p.expenses.map(e=>e.date.slice(0,4))))].sort();return title('APRENDIZADO ENTRE EMPREENDIMENTOS','A próxima obra começa mais informada.','Compare preços unitários e custos completos. Valores nominais, sem correção pela inflação.',btn('history-export','↓ Exportar comparativo'))+
 `<section class="card"><div class="section-head"><h2>Preço da mesma especificação ao longo dos anos</h2></div><form class="filters" id="history-filters">${select('a','Ano de referência',choices(allYears),years.a)}${select('b','Ano de comparação',choices(allYears),years.b)}<button class="btn">Comparar</button></form><p class="fine">Agrupa descrição, natureza e unidade de medida iguais; preço médio ponderado pela quantidade contratada. Exclui terreno, taxas e valores globais em verba, lote ou contrato; compare o escopo completo na tabela de empreendimentos. Mantenha as especificações consistentes. Compras de qualidade ou escopo diferentes devem ter descrições diferentes.</p><div class="table-scroll"><table><thead><tr><th>Material / serviço</th><th>Medida</th><th>${years.a} · preço médio</th><th>${years.b} · preço médio</th><th>Variação nominal</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${KINDS[r.kind]}</small></td><td>${esc(r.uom)}</td><td>${r.priceA!==null?money(Math.round(r.priceA)):'Sem registros'}</td><td>${r.priceB!==null?money(Math.round(r.priceB)):'Sem registros'}</td><td>${r.change!==null?tag((r.change>0?'+':'')+pct(r.change),r.change>0?'rose':'green'):'—'}</td></tr>`).join('')}</tbody></table></div></section>
 <section class="card section-gap"><h2>Comparativo dos empreendimentos</h2><p class="fine">Obras abertas mostram previsão. Encerradas mostram os custos efetivamente registrados. Venda e lucro continuam estimados; não há recebimentos de vendas nesta versão.</p><div class="table-scroll"><table><thead><tr><th>Empreendimento / início</th><th>Situação</th><th>Área</th><th>Custo completo</th><th>Custo/m²</th><th>Mão de obra¹</th><th>Participação da mão de obra</th><th>Lucro estimado</th></tr></thead><tbody>${projects().map(p=>{const t=totals(p),labor=sum(p.expenses.filter(e=>!e.cancelled&&e.kind==='labor'),'total');return `<tr><td><strong>${esc(p.name)}</strong><small>${brDate(p.start)}</small></td><td>${tag(p.status==='closed'?'Encerrada':'Em andamento',p.status==='closed'?'green':'blue')}</td><td>${fmt(t.area)} m²</td><td>${money(t.forecast)}</td><td>${money(t.costPerSqm)}</td><td>${money(labor)}</td><td>${t.contracted?pct(labor/t.contracted):'—'}</td><td>${money(t.profit)}</td></tr>`;}).join('')}</tbody></table></div><p class="fine">¹ Mão de obra contratada / custos contratados. A comparação inclui terreno, padrão, localização e fases diferentes: não isola inflação ou produtividade.</p></section><section class="card section-gap"><h2>Histórico de alterações desta obra</h2><div class="audit-list">${state.audit.filter(a=>a.projectId===p.id).slice(-15).reverse().map(a=>`<div><span>${brDate(a.date)} · ${esc(actionName(a.type))}</span><strong>${esc(a.description||'Registro financeiro atualizado')}</strong></div>`).join('')}</div></section>`;}
function actionName(type){return ({'project.trash':'Empreendimento movido para a lixeira','project.restore':'Empreendimento restaurado','project.create':'Empreendimento criado','project.update':'Premissas atualizadas','unit.add':'Unidade adicionada','expense.quick':'Gasto rápido registrado','contractor.save':'Contrato de empreiteiro registrado / atualizado','sale.save':'Venda registrada / atualizada','unit.commercial':'Laudo / documentos da casa atualizados','sale.receipt':'Recebimento de venda registrado','sale.receipt.reverse':'Recebimento estornado','sale.cancel':'Venda cancelada','expense.construction':'Classificação da construção atualizada','unit.save':'Unidade atualizada','stage.save':'Etapa / orçamento atualizado','expense.save':'Custo registrado / atualizado','expense.cancel':'Custo cancelado','payment.add':'Pagamento registrado','payment.reverse':'Pagamento estornado','material.use':'Consumo de material','project.close':'Obra encerrada','project.reopen':'Obra reaberta','comparable.save':'Referência de mercado'})[type]||type;}
function projectForm(p){
  const basics=field('name','Nome do empreendimento',p?.name||'','text','required maxlength="150"')+field('neighborhood','Bairro',p?.neighborhood||'Vila Tupi','text','required list="neighborhoods"')+select('zone','Zona de localização',choices(['Zona 1','Zona 2','Zona 3','Não informada']),p?.zone||'Zona 2')+select('type','Tipo do imóvel',[['condominium','Sobrados em condomínio'],['individual','Sobrado individual']],p?.type||'condominium')+field('address','Endereço',p?.address||'')+field('start','Início / aquisição',p?.start||today(),'date','required')+number('bedrooms','Dormitórios sugeridos para novas unidades',p?.bedrooms||2,1,'1')+select('allocation','Rateio padrão de custos comuns',[['area','Por área privativa'],['equal','Igual por unidade']],p?.allocation||'area');
  const initial=p?'':`<h3 class="wide form-section">As unidades e o terreno</h3><p class="wide fine">Cada casa pode ter medidas, dormitórios e preço próprios. Os valores abaixo são sugestões para campos ainda não personalizados.</p>${number('count','Quantidade inicial de unidades',7,1,'1')}${number('area','Área sugerida (m²)',62,.01)}${number('sale','Venda sugerida (R$)',0)}<div class="wide"><button type="button" class="btn" id="resize-units" aria-controls="unit-rows">Ajustar quantidade de unidades</button><button type="button" class="btn" id="undo-units" hidden>Desfazer ajuste</button><p class="fine">Ajusta a lista ao número informado. As sugestões preenchem os campos ainda não personalizados. Você pode desfazer o último ajuste antes de salvar.</p><p id="unit-feedback" class="callout" role="status" tabindex="-1" hidden></p></div><div id="unit-rows" class="wide unit-editor-list"></div>${number('land','Valor do terreno (R$)',0)}${number('commission','Comissão da aquisição (R$)',0)}${number('taxes','Impostos / taxas iniciais (R$)',0)}${check('acquisitionPaid','Terreno, comissão e impostos acima já foram pagos na data inicial')}<p class="fine wide">Os valores entram uma única vez na planilha de custos. Sem a marcação de pagamento, ficam contratados a pagar. As características de cada unidade também poderão ser editadas depois.</p><h3 class="wide form-section">Como será contratada a mão de obra?</h3>${select('laborMode','Formato',[['separate','Serviços separados / cadastrar depois'],['sqm','Empreitada por m²'],['fixed','Empreitada com valor fechado']],'separate')}${number('laborRate','Preço por m² ou valor fechado (R$)',0)}${field('coverage','Serviços incluídos na empreitada (separados por vírgula)','Pedreiro,Servente')}${area('laborNotes','Escopo e observações da contratação','')}<p class="fine wide">Por m²: preço × soma da área privativa das unidades. Áreas comuns contratadas além dessa base devem ser incluídas ao editar a quantidade da empreitada. Serviços cobertos não devem ser lançados novamente.</p>`;
  dialog(p?'Editar empreendimento':'Novo empreendimento',basics+initial+`<h3 class="wide form-section">Premissas de viabilidade</h3>${number('reserveBps','Reserva para imprevistos (%)',p?val(p.reserveBps):5)}${number('sellingBps','Despesas sobre a venda (%)',p?val(p.sellingBps):0)}${number('targetBps','Margem de lucro desejada (%)',p?val(p.targetBps):20)}<p class="fine wide">Despesas de venda incluem o percentual que você informar para comissão e outras despesas. Não há alíquota oficial pré-preenchida. A reserva incide sobre todo o custo previsto.</p>${area('notes','Anotações',p?.notes||'')}`,f=>{const d=Object.fromEntries(f);for(const k of ['reserveBps','sellingBps','targetBps'])d[k]=decimal(d[k]);d.bedrooms=Number(d.bedrooms);if(p){d.projectId=p.id;return save('project.update',d);}else{for(const k of ['area','sale','land','commission','taxes','laborRate'])d[k]=decimal(d[k]);d.units=readUnitRows();if(Number(d.count)!==d.units.length)throw new Error('A quantidade informada difere das unidades abaixo. Use Ajustar para acrescentar ou Remover em cada linha.');d.count=d.units.length;d.acquisitionPaid=f.has('acquisitionPaid');return save('project.create',d);}});
  if(!p){
    const form=$('#editor'),host=$('#unit-rows'),feedback=$('#unit-feedback'),undo=$('#undo-units');
    let unitRowSeq=0,previous=null;
    const rows=()=>[...host.children];
    const announce=message=>{feedback.textContent=message;feedback.hidden=false;feedback.focus();};
    const numberRows=()=>rows().forEach((row,i)=>row.querySelector('legend').textContent='Casa / unidade '+(i+1));
    const snapshot=()=>{previous=rows().map(row=>({row,fields:[...row.querySelectorAll('input')].map(input=>({input,value:input.value,defaultValue:input.defaultValue}))}));undo.hidden=false;};
    const suggestions=()=>({area:form.elements.area.value,bedrooms:form.elements.bedrooms.value,sale:form.elements.sale.value});
    const add=()=>{const taken=new Set(rows().map(row=>row.querySelector('[data-unit="name"]').value.trim().toLowerCase()));let n=1;while(taken.has(('Unidade '+String(n).padStart(2,'0')).toLowerCase()))n++;host.insertAdjacentHTML('beforeend',unitRow(unitRowSeq++,{name:'Unidade '+String(n).padStart(2,'0'),...suggestions()}));};
    for(let i=0;i<Number(form.elements.count.value);i++)add();
    $('#resize-units').onclick=()=>{
      const n=Number(form.elements.count.value);
      if(!Number.isInteger(n)||n<1||n>100){announce('Informe de 1 a 100 unidades.');return;}
      for(const name of ['area','bedrooms','sale'])if(!form.elements[name].reportValidity())return;
      snapshot();const removed=Math.max(0,host.children.length-n),defaults=suggestions();
      while(host.children.length>n)host.lastElementChild.remove();
      for(const row of rows())for(const [key,value] of Object.entries(defaults)){const input=row.querySelector('[data-unit="'+key+'"]');if(input.value===input.defaultValue){input.value=value;input.defaultValue=value;}}
      while(host.children.length<n)add();
      numberRows();$('#form-error').textContent='';
      announce(n+' unidade(s) na lista abaixo.'+(removed?' '+removed+' unidade(s) retirada(s); use Desfazer ajuste para recuperá-las.':'')+' Os campos personalizados foram preservados.');
    };
    undo.onclick=()=>{if(!previous)return;for(const item of previous)for(const field of item.fields){field.input.defaultValue=field.defaultValue;field.input.value=field.value;}host.replaceChildren(...previous.map(item=>item.row));form.elements.count.value=previous.length;previous=null;undo.hidden=true;numberRows();announce('A lista anterior foi recuperada. '+host.children.length+' unidade(s).');};
    host.onclick=e=>{const button=e.target.closest('[data-remove-unit]');if(!button)return;if(host.children.length===1){announce('Mantenha ao menos uma unidade.');return;}snapshot();button.closest('.unit-editor').remove();form.elements.count.value=host.children.length;numberRows();announce('Unidade retirada. '+host.children.length+' unidade(s) na lista. Você pode desfazer o ajuste.');};
  }
}
function unitRow(i,u){return `<fieldset class="unit-editor"><legend>Casa / unidade ${i+1}</legend><div class="form-grid">${field('uname'+i,'Identificação',u.name,'text','required maxlength="100" data-unit="name"')}${field('uarea'+i,'Área privativa (m²)',u.area,'number','required min="0.01" step="0.01" data-unit="area"')}${field('ubed'+i,'Dormitórios',u.bedrooms,'number','required min="1" max="10" step="1" data-unit="bedrooms"')}${field('usale'+i,'Venda estimada (R$)',u.sale,'number','required min="0" step="0.01" data-unit="sale"')}${field('ubath'+i,'Banheiros (opcional)','','number','min="0" max="20" step="1" data-unit="bathrooms"')}${field('uparking'+i,'Vagas (opcional)','','number','min="0" max="20" step="1" data-unit="parking"')}${field('unotes'+i,'Observações da unidade','','text','maxlength="2000" data-unit="notes"')}<button type="button" class="btn" data-remove-unit>Remover esta unidade</button></div></fieldset>`;}
function readUnitRows(){return [...document.querySelectorAll('.unit-editor')].map(row=>{const u=Object.fromEntries([...row.querySelectorAll('[data-unit]')].map(input=>[input.dataset.unit,input.value]));for(const k of ['area','sale'])u[k]=decimal(u[k]);u.bedrooms=Number(u.bedrooms);for(const k of ['bathrooms','parking'])u[k]=u[k]===''?null:Number(u[k]);return u;});}
function unitForm(p,u){dialog(u?'Editar unidade':'Adicionar unidade',field('name','Nome / identificação',u?.name||'','text','required maxlength="100"')+number('area','Área privativa (m²)',u?val(u.area):'',.01)+number('bedrooms','Dormitórios',u?.bedrooms??p.bedrooms,1,'1')+number('sale','Venda estimada (R$)',u?val(u.sale):0)+field('bathrooms','Banheiros (opcional)',u?.bathrooms??'','number','min="0" max="20" step="1"')+field('parking','Vagas (opcional)',u?.parking??'','number','min="0" max="20" step="1"')+area('notes','Observações da unidade',u?.notes||'')+`<p class="fine wide">Custos já registrados mantêm seu rateio. Novas unidades participam dos próximos rateios e da previsão restante. Confira a empreitada contratada caso a área total mude.</p>`,f=>{const d=Object.fromEntries(f);d.area=decimal(d.area);d.sale=decimal(d.sale);d.bedrooms=Number(d.bedrooms);for(const k of ['bathrooms','parking'])d[k]=d[k]===''?null:Number(d[k]);return save(u?'unit.save':'unit.add',{...d,projectId:p.id,...(u?{id:u.id}:{})});});}


const COST_SHORTCUTS=[
 ['Impostos e taxas','Impostos e taxas','fees',1],['Cimento','Material','material',5],['Pregos','Material','material',4],['Areia','Material','material',5],['Brita','Material','material',3],['Tijolos e blocos','Material','material',5],['Madeira','Material','material',6],['Aço e ferragens','Material','material',4],['Alumínio','Material','material',12],['Materiais da obra','Material','material',5],['Tubos e conexões','Hidráulica','material',8],['Fios e cabos','Elétrica','material',7],['Pisos e revestimentos','Material','material',10],['Tintas','Pintura','material',11],['Impermeabilizante','Impermeabilização','material',9],['Pedreiro','Pedreiro','labor',16],['Servente','Servente','labor',16],['Locação de equipamentos','Equipamentos e locação','equipment',2],['Frete','Transporte','extra',2],['Caçamba','Retirada de entulho','equipment',2],['Água e energia','Contas da obra','fees',2],['Projetos e licenças','Projetos e licenças','fees',1]
];
function quickCatalog(){return `<section class="card quick-catalog"><div class="section-head"><div><h2>O que você gastou hoje?</h2><p>Escolha um item, informe o valor e indique se já foi pago. Você pode mudar o nome e a categoria.</p></div></div><div class="quick-items">${COST_SHORTCUTS.map((x,i)=>btn('expense-quick',esc(x[0]),String(i))).join('')}${btn('expense-quick','+ Outro gasto')}</div></section>`;}
const expenseStageOptions=p=>[['','Não informar'],...p.stages.filter(st=>!st.unassigned).map(st=>[st.id,st.name])];
function quickExpenseForm(p,index){
  const item=index!==''?COST_SHORTCUTS[Number(index)]:null;
  const [description,category,kind]=item||['','Material','material'];
  dialog('Registrar gasto rápido',`<p class="callout wide">${esc(p.name)} · Este lançamento entra uma única vez nos custos. Se estiver pago, o pagamento é registrado junto.</p>`+field('description','O que foi comprado ou contratado?',description,'text','required maxlength="300"')+number('cents','Valor total do gasto (R$)','',.01)+select('paymentStatus','Situação do gasto',[['paid','Já paguei'],['pending','Ainda vou pagar']],'paid')+field('date','Data da compra / pagamento',today(),'date','required')+select('mode','Onde aplicar o gasto?',[['area','Obra inteira · por área'],['equal','Obra inteira · partes iguais'],['direct','Somente uma unidade']],p.allocation)+select('unitId','Unidade (se o gasto for direto)',p.units.map(u=>[u.id,u.name]),p.units[0].id)+select('stageId','Etapa da obra',expenseStageOptions(p),'')+select('method','Forma de pagamento',choices(['PIX','Transferência','Boleto','Dinheiro','Cartão','Outro']),'PIX')+field('due','Vencimento (se ainda for pagar)',today(),'date','required')+`<details class="wide quick-details"><summary>Categoria, fornecedor e outros detalhes</summary><div class="form-grid">`+field('category','Categoria (pode criar outra)',category,'text','required list="categories" maxlength="100"')+select('kind','Natureza do gasto',Object.entries(KINDS),kind)+field('supplier','Fornecedor (opcional)','')+field('reference','Nota / referência (opcional)','')+area('notes','Observações','')+check('extraToContract','Mão de obra adicional, fora da empreitada existente')+`</div></details><p class="fine wide">Registro por valor total, sem quantidade física. Para controlar sacos, quilos ou metros, use Lançamento detalhado. A etapa é opcional. Nenhuma transferência bancária é realizada.</p>`,f=>{const d=Object.fromEntries(f);d.cents=decimal(d.cents);d.extraToContract=f.has('extraToContract');return save('expense.quick',{...d,projectId:p.id});},'Salvar gasto');
  $('#editor').addEventListener('invalid',e=>{const details=e.target.closest('details');if(details)details.open=true;},true);
  const sync=()=>{const form=$('#editor'),paidNow=form.elements.paymentStatus.value==='paid';form.elements.method.disabled=!paidNow;form.elements.method.closest('label').hidden=!paidNow;form.elements.due.disabled=paidNow;form.elements.due.closest('label').hidden=paidNow;form.elements.unitId.disabled=form.elements.mode.value!=='direct';form.elements.unitId.closest('label').hidden=form.elements.mode.value!=='direct';};
  $('#editor').elements.paymentStatus.onchange=sync;$('#editor').elements.mode.onchange=sync;sync();
}

function expenseForm(p,e){dialog(e?'Editar custo da obra':'Lançar custo da obra',field('description','Descrição / especificação',e?.description||'','text','required maxlength="300"')+field('category','Categoria (pode criar outra)',e?.category||'Material','text','required list="categories" maxlength="100"')+select('kind','Natureza do custo',Object.entries(KINDS),e?.kind||'material')+select('constructionScope','Participação na construção por m²',Object.entries(CONSTRUCTION_SCOPES),e?.constructionScope||'auto')+select('stageId','Etapa da obra',expenseStageOptions(p),p.stages.find(st=>st.id===e?.stageId)?.unassigned?'':e?.stageId||'')+field('supplier','Fornecedor / empreiteiro',e?.supplier||'')+field('reference','Nota / referência / contrato',e?.reference||'')+field('date','Data da contratação / compra',e?.date||today(),'date','required')+field('due','Vencimento previsto',e?.due||today(),'date','required')+number('qty','Quantidade',e?val(e.qty,1000):1,.001,'0.001')+field('uom','Unidade de medida (m², saco, verba...)',e?.uom||'verba','text','required maxlength="30"')+number('unitCents','Preço unitário (R$)',e?val(e.unitCents):0)+`<div class="calculated"><span>Total contratado</span><strong id="expense-total">${money(e?.total||0)}</strong></div>`+select('mode','Distribuição do custo',[['area','Comum · proporcional à área'],['equal','Comum · igual por unidade'],['direct','Direto · uma unidade']],e?.mode||p.allocation)+select('unitId','Unidade (somente custo direto)',p.units.map(u=>[u.id,u.name]),e?.unitId||p.units[0].id)+field('coverage','Se empreitada: serviços cobertos, separados por vírgula',e?.coverage||'')+check('extraToContract','Este serviço é adicional e não está incluído na empreitada existente',e?.extraToContract)+area('notes','Detalhes, justificativa ou custo fora do comum',e?.notes||'')+`<p class="fine wide">O lançamento registra o compromisso; os pagamentos são registrados depois, inclusive parciais. Para valor fechado, use quantidade 1 e medida “verba” ou “contrato”. ${e?'Salvar recalcula o rateio com as áreas atuais.':''}${e&&e.kind==='material'&&!tracksQuantity(e)?' Este gasto já está nos custos: ao informar quantidade e preço unitário, mantenha o total contratado para não alterar seu valor.':''}</p>`,f=>{const d=Object.fromEntries(f);d.qty=decimal(d.qty,3);d.unitCents=decimal(d.unitCents);d.extraToContract=f.has('extraToContract');return save('expense.save',{...d,projectId:p.id,...(e?{id:e.id}:{})});});
  $('#editor').oninput=()=>{try{$('#expense-total').textContent=money(amount(decimal($('#editor [name="unitCents"]').value),decimal($('#editor [name="qty"]').value,3)));}catch{$('#expense-total').textContent='Preencha os valores';}};
}
function expenseDetail(p,e){dialog('Detalhamento do custo',`<div class="wide"><h3>${esc(e.description)}</h3><p>${esc(e.category)} · ${esc(p.stages.find(st=>st.id===e.stageId).name)} · ${esc(e.supplier||'Sem fornecedor')}</p><div class="mini-stats"><div><strong>${money(e.total)}</strong><span>Contratado</span></div><div><strong>${money(paid(e))}</strong><span>Pago</span></div><div><strong>${money(e.total-paid(e))}</strong><span>A pagar</span></div></div><p>${esc(e.notes||'Sem observação adicional.')}</p>${e.coverage?`<p><strong>Incluído na empreitada:</strong> ${esc(e.coverage)}</p>`:''}<h3>Distribuição por unidade</h3><div class="allocation-list">${Object.entries(e.allocation).map(([id,n])=>`<div><span>${esc(p.units.find(u=>u.id===id).name)}</span><strong>${money(n)}</strong></div>`).join('')}</div><h3>Pagamentos</h3>${paymentRows(p,e)}<div class="actions section-gap">${p.status!=='closed'?btn('expense-edit','Editar custo',e.id)+btn('payment','Registrar pagamento',e.id)+(!e.saleId&&!paid(e)&&!used(e)?btn('expense-cancel','Cancelar lançamento',e.id,'danger'):''):''}</div></div>`,()=>{},'Fechar');}

const paymentStage=(p,pay)=>p.stages.find(st=>st.id===pay.stageId)?.name||'Não informada';
function paymentRows(p,e){return e.payments.length?`<div class="table-scroll"><table><thead><tr><th>Pagamento</th><th>Valor</th><th>Etapa / observação</th><th>Situação</th></tr></thead><tbody>${[...e.payments].sort((a,b)=>b.date.localeCompare(a.date)).map(pay=>`<tr><td>${brDate(pay.date)}<small>${esc(pay.method)}${pay.reference?' · '+esc(pay.reference):''}</small></td><td>${money(pay.cents)}</td><td>${esc(paymentStage(p,pay))}${pay.notes?`<small class="contract-scope">${esc(pay.notes)}</small>`:''}</td><td>${pay.reversed?tag('Estornado: '+pay.reversed,'rose'):tag('Pago','green')+(p.status!=='closed'?btn('payment-reverse','Estornar',e.id+'|'+pay.id):'')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="fine">Nenhum vale ou pagamento registrado.</p>';}
function contractorsPage(p){const rows=p.expenses.filter(e=>!e.cancelled&&isContractor(e)),others=p.expenses.filter(e=>!e.cancelled&&e.kind==='labor'&&!isContractor(e)),closed=p.status==='closed',total=sum(rows,'total'),settled=sum(rows,paid);
 return title('MÃO DE OBRA','Empreiteiro','Contratos, serviços combinados e cada vale da obra.',closed?'':btn('contractor-new','+ Cadastrar empreiteiro','','primary'))+`<div class="metrics three">${metric('Valor total dos serviços',money(total),rows.length+' contrato(s)')}${metric('Já pago',money(settled),'Vales e pagamentos confirmados')}${metric('A pagar',money(total-settled),'Saldo dos contratos')}</div><p class="callout">Os contratos entram uma única vez nos custos da obra. Registre os vales aqui para abater o saldo.${others.length?' Há outros custos de mão de obra nesta base: confira os lançamentos anteriores antes de cadastrar um novo contrato.':''}</p>${!closed&&others.length?`<div class="actions section-gap">${btn('contractor-existing','Aproveitar custo já lançado')}</div>`:''}`+(rows.length?rows.map(e=>`<article class="card contractor-card"><div class="section-head"><div><p class="eyebrow">EMPREITEIRO</p><h2>${esc(e.supplier||'Nome ainda não informado')}</h2><p>${esc(e.description)} · ${e.uom==='m²'?`${fmt(e.qty/1000)} m² × ${money(e.unitCents)}/m²`:'Valor fechado'}</p></div><div class="actions">${!closed?btn('contractor-edit','Editar contrato',e.id)+(e.total>paid(e)?btn('payment','+ Registrar vale',e.id,'primary'):''):''}</div></div><div class="mini-stats"><div><strong>${money(e.total)}</strong><span>Total do serviço</span></div><div><strong>${money(paid(e))}</strong><span>Já pago</span></div><div><strong>${money(e.total-paid(e))}</strong><span>A pagar</span></div></div><h3>Serviços incluídos</h3><p class="contract-scope">${esc(e.coverage||'Preencha o escopo ao editar o contrato.')}</p>${e.notes?`<p class="contract-scope fine">${esc(e.notes)}</p>`:''}${e.contractFile?`<p>${btn('contractor-file','↓ Baixar contrato',e.id)} <span class="fine">${esc(e.contractFile.name)}</span></p>`:'<p class="fine">Contrato sem anexo.</p>'}<h3>Vales e pagamentos</h3>${paymentRows(p,e)}<div class="actions section-gap">${btn('expense-detail','Ver custo e rateio',e.id)}${!closed&&!paid(e)?btn('expense-cancel','Cancelar contrato',e.id,'danger'):''}</div></article>`).join(''):emptyView('Cadastre o empreiteiro da obra','Informe o preço combinado, os serviços incluídos e acompanhe o saldo de cada contrato.'));
}

function salesSummary(p){const t=salesTotals(p);return `<section class="card section-gap sales-summary"><div class="section-head"><div><span class="eyebrow">VENDAS E CAIXA</span><h2>Entradas do empreendimento</h2></div>${btn('nav','Ver recebimentos →','receipts')}</div><div class="metrics three">${metric('Valor vendido',money(t.sold),t.rows.length+' casa(s) vendida(s)')}${metric('Já recebido',money(t.received),'Somente recebimentos confirmados','green')}${metric('A receber',money(t.pending),'Saldo dos contratos')}</div></section>`;}
function salesPage(p){const t=salesTotals(p),closed=p.status==='closed';return title('CADA CASA, SEU CONTRATO','Vendas / contratos','Acompanhe a venda, a comissão, o laudo e os documentos de cada unidade.',btn('nav','Entradas / recebidos →','receipts'))+`<div class="metrics three">${metric('Casas disponíveis',String(t.available),p.units.length+' unidades no empreendimento')}${metric('Casas vendidas',String(t.rows.length),money(t.sold)+' contratados')}${metric('Comissões das vendas',money(t.commission),'Incluídas automaticamente nos custos')}</div>${closed?'<p class="callout">Obra encerrada financeiramente. Reabra em Empreendimento para registrar ou alterar vendas, comissões e recebimentos.</p>':''}<div class="units-grid sales-grid">${p.units.map(u=>{const sale=activeSale(p,u.id),c=u.commercial,e=sale&&p.expenses.find(e=>e.id===sale.commissionExpenseId),commissionPaid=e&&!e.cancelled?paid(e):0;return `<article class="unit-card sales-card"><div class="section-head"><h2>${esc(u.name)}</h2>${tag(sale?'Vendida':'Disponível',sale?'blue':'green')}</div><p>${fmt(u.area/100)} m² · ${u.bedrooms??p.bedrooms} dormitórios</p><dl>${sale?`<div><dt>Valor da venda</dt><dd>${money(sale.price)}</dd></div><div><dt>Já recebido</dt><dd>${money(received(sale))}</dd></div><div><dt>A receber</dt><dd>${money(sale.price-received(sale))}</dd></div><div><dt>Comissão</dt><dd>${money(sale.commissionCents)}<small>${commissionPaid===sale.commissionCents?(sale.commissionCents?'Paga':'Sem comissão'):commissionPaid?'Parcial · '+money(commissionPaid)+' pagos':'A pagar'}</small></dd></div>`:`<div><dt>Venda estimada</dt><dd>${money(u.sale)}</dd></div>`}<div><dt>Laudo da casa</dt><dd>${c?.hasAppraisal?money(c.appraisalCents):'Não informado / sem laudo'}</dd></div></dl>${sale?`<p><strong>${esc(SALE_MODES[sale.paymentMode])}</strong><br>Vendido por: ${esc(sale.seller||'Não informado')}<br>Comprador: ${esc(sale.buyer||'Não informado')}</p>${sale.terms?`<p class="contract-scope fine">${esc(sale.terms)}</p>`:''}`:''}<div class="actions">${sale?btn('sale-detail','Ver venda e parcelas',sale.id):closed?'':btn('sale-new','Registrar venda',u.id,'primary')}${!closed?btn('unit-commercial','Laudo / documentos',u.id):''}</div><div class="sales-documents">${Object.entries(c?.documents||{}).map(([kind,file])=>btn('sale-document','↓ '+esc(SALE_DOCUMENTS[kind]),u.id+'|'+kind)).join('')||'<p class="fine">Nenhum documento anexado.</p>'}</div></article>`;}).join('')}</div><p class="fine">Comissões entram nos custos gerais da obra e continuam fora da construção por m². Registrar uma venda cria valores a receber; só a confirmação do recebimento entra no caixa.</p>${(p.sales||[]).some(s=>s.cancelled)?`<details class="quick-details section-gap"><summary>Vendas canceladas</summary>${p.sales.filter(s=>s.cancelled).map(s=>`<div class="payment-row"><div><strong>${esc(p.units.find(u=>u.id===s.unitId).name)}</strong><small>${esc(s.cancelled)}</small></div>${btn('sale-detail','Ver histórico',s.id)}</div>`).join('')}</details>`:''}`;}
function saleInstallments(p,sale){return `<div class="table-scroll"><table><thead><tr><th>Parcela</th><th>Vencimento</th><th>Valor</th><th>Recebido</th><th>Saldo</th><th></th></tr></thead><tbody>${sale.installments.map(i=>{const n=received(sale,i.id),balance=i.cents-n;return `<tr><td>${esc(i.label)}</td><td>${brDate(i.due)}</td><td>${money(i.cents)}</td><td>${money(n)}</td><td>${money(balance)}<small>${balance?(i.due<today()?'Vencido':'A receber'):'Recebida'}</small></td><td>${balance&&!sale.cancelled&&p.status!=='closed'?btn('sale-receipt','Registrar recebimento',sale.id+'|'+i.id):''}</td></tr>`;}).join('')}</tbody></table></div>`;}
function saleReceiptHistory(p,sale){return sale.receipts.length?`<div class="table-scroll"><table><thead><tr><th>Data / parcela</th><th>Recebido</th><th>Forma / observação</th><th>Situação</th></tr></thead><tbody>${[...sale.receipts].sort((a,b)=>b.date.localeCompare(a.date)).map(r=>`<tr><td>${brDate(r.date)}<small>${esc(sale.installments.find(i=>i.id===r.installmentId).label)}</small></td><td>${money(r.cents)}</td><td>${esc(r.method)}<small>${esc(r.reference)} ${esc(r.notes)}</small></td><td>${r.reversed?tag('Estornado: '+r.reversed,'rose'):tag('Confirmado','green')+(p.status!=='closed'&&!sale.cancelled?btn('sale-receipt-reverse','Estornar',sale.id+'|'+r.id):'')}</td></tr>`).join('')}</tbody></table></div>`:'<p>Nenhum recebimento confirmado.</p>';}
function receiptsPage(p){const t=salesTotals(p);return title('ENTRADAS DO CONDOMÍNIO','Entradas / recebidos','Valores vendidos, parcelas pendentes e dinheiro efetivamente recebido.',btn('receipts-export','↓ Exportar recebimentos CSV')+btn('nav','Vendas / contratos →','sales'))+salesSummary(p)+(t.rows.length?t.rows.map(sale=>`<section class="card section-gap"><div class="section-head"><div><h2>${esc(p.units.find(u=>u.id===sale.unitId).name)}</h2><p>${esc(sale.buyer||'Comprador não informado')} · ${esc(SALE_MODES[sale.paymentMode])}</p></div>${btn('sale-detail','Ver contrato',sale.id)}</div>${saleInstallments(p,sale)}<details class="quick-details section-gap"><summary>Histórico de recebimentos (${sale.receipts.length})</summary>${saleReceiptHistory(p,sale)}</details></section>`).join(''):emptyView('Nenhuma venda registrada.','Cadastre a venda de uma casa para acompanhar suas entradas e recebimentos.',btn('nav','Abrir vendas','sales')));}
function saleDetail(p,sale){const u=p.units.find(u=>u.id===sale.unitId),e=p.expenses.find(e=>e.id===sale.commissionExpenseId);dialog('Venda · '+esc(u.name),`<div class="wide"><p>${sale.cancelled?tag('Cancelada: '+sale.cancelled,'rose'):tag('Vendida','blue')} · ${brDate(sale.date)} · ${esc(SALE_MODES[sale.paymentMode])}</p><p>Comprador: ${esc(sale.buyer||'Não informado')}<br>Vendedor: ${esc(sale.seller||'Não informado')}</p><div class="mini-stats"><div><strong>${money(sale.price)}</strong><span>Valor vendido</span></div><div><strong>${money(received(sale))}</strong><span>Recebido</span></div><div><strong>${money(sale.price-received(sale))}</strong><span>A receber</span></div></div><h3>Condições da venda</h3><p class="contract-scope">${esc(sale.terms||'Sem detalhes adicionais.')}</p><p class="contract-scope fine">${esc(sale.notes)}</p><h3>Parcelas</h3>${saleInstallments(p,sale)}<h3>Recebimentos</h3>${saleReceiptHistory(p,sale)}<h3>Comissão</h3><p>${money(sale.commissionCents)} · ${e&&!e.cancelled?money(paid(e))+' pagos':sale.cancelled?'Venda cancelada':'Sem comissão'}</p><div class="actions">${e&&!e.cancelled?btn('expense-detail','Ver custo / pagamento da comissão',e.id):''}${!sale.cancelled&&p.status!=='closed'?btn('sale-edit','Editar venda',sale.id)+btn('sale-cancel','Cancelar venda',sale.id,'danger'):''}</div></div>`,()=>{},'Fechar');}
function saleForm(p,u,sale){const locked=!!sale?.receipts.length,e=sale&&p.expenses.find(e=>e.id===sale.commissionExpenseId);dialog(sale?'Editar venda · '+esc(u.name):'Registrar venda · '+esc(u.name),`<p class="callout wide">O preço vendido entra na projeção da casa. As parcelas entram em A receber e a comissão gera um único custo vinculado. Confirme abaixo somente os valores que já recebeu.</p>`+field('buyer','Nome do comprador (opcional)',sale?.buyer||'')+field('seller','Quem vendeu / corretor (opcional)',sale?.seller||'')+number('price','Valor da venda (R$)',val(sale?.price??u.sale),.01)+field('date','Data da venda',sale?.date||today(),'date','required')+select('paymentMode','Como foi a venda?',Object.entries(SALE_MODES),sale?.paymentMode||'cash')+field('balanceDue','Vencimento da venda / saldo final',sale?.balanceDue||today(),'date','required')+`<div class="form-grid wide sales-entry" id="sales-entry">`+number('entryCents','Valor total da entrada (R$)',val(sale?.entryCents||0))+number('entryCount','Número de parcelas da entrada',sale?.entryCount||1,1,'1')+field('entryFirstDue','Primeiro vencimento da entrada',sale?.entryFirstDue||today(),'date','required')+`</div><p class="callout wide" id="sale-plan-preview" aria-live="polite"></p>${locked?'<p class="fine wide">Valores e parcelas foram preservados porque a venda já tem histórico de recebimentos. Para refazer o contrato, estorne os recebimentos e cancele a venda anterior.</p>':''}`+area('terms','Como a venda foi combinada? Condições e detalhes',sale?.terms||'')+`<h3 class="form-section wide">Comissão da venda</h3>`+number('commissionCents','Valor da comissão (R$)',val(sale?.commissionCents||0))+select('commissionStatus','Situação da comissão',sale?[['preserve','Manter situação atual'],['paid','Já foi paga'],['pending','Não foi paga']]:[['pending','Não foi paga'],['paid','Já foi paga']],sale?'preserve':'pending')+field('commissionPaidDate','Data do pagamento da comissão',e?.payments.filter(r=>!r.reversed).at(-1)?.date||today(),'date',`max="${today()}"`)+(sale?`<p class="fine wide">Comissão atual: ${money(sale.commissionCents)}; pagos: ${money(e&&!e.cancelled?paid(e):0)}. O mesmo custo será atualizado.</p>`+area('correctionReason','Justificativa se corrigir uma comissão já paga'):'')+(!sale?`<h3 class="form-section wide">Entrada de dinheiro já confirmada</h3>`+number('receivedNow','Valor já recebido nesta venda (R$)',0)+field('receivedDate','Data do recebimento',today(),'date',`max="${today()}"`)+select('receivedMethod','Forma do recebimento',choices(['PIX','Transferência','Dinheiro','Boleto','Financiamento liberado','Outro']),'PIX')+`<p class="fine wide">Deixe zero se ainda não recebeu. Um valor parcial abate as parcelas na ordem da entrada e depois o saldo final.</p>`:'')+area('notes','Observações internas (opcional)',sale?.notes||''),f=>{
 const config=locked?Object.fromEntries(['price','date','paymentMode','entryCents','entryCount','entryFirstDue','balanceDue'].map(k=>[k,sale[k]])):{price:decimal(f.get('price')),date:f.get('date'),paymentMode:f.get('paymentMode'),entryCents:f.get('entryCents')===null?0:decimal(f.get('entryCents')),entryCount:Number(f.get('entryCount')||1),entryFirstDue:f.get('entryFirstDue')||f.get('date'),balanceDue:f.get('balanceDue')};return save('sale.save',{projectId:p.id,unitId:u.id,...(sale?{id:sale.id}:{}),...config,buyer:f.get('buyer'),seller:f.get('seller'),terms:f.get('terms'),notes:f.get('notes'),commissionCents:decimal(f.get('commissionCents')),commissionStatus:f.get('commissionStatus'),commissionPaidDate:f.get('commissionPaidDate'),correctionReason:f.get('correctionReason')||'',receivedNow:sale?0:decimal(f.get('receivedNow')),receivedDate:f.get('receivedDate'),receivedMethod:f.get('receivedMethod')});},'Salvar venda');
 const form=$('#editor'),refresh=()=>{const mode=form.elements.paymentMode.value,entry=['entry_installments','financed'].includes(mode);$('#sales-entry').hidden=!entry;for(const key of ['entryCents','entryCount','entryFirstDue'])form.elements[key].disabled=!entry||locked;for(const key of ['price','date','paymentMode','balanceDue'])form.elements[key].disabled=locked;form.elements.commissionPaidDate.disabled=form.elements.commissionStatus.value!=='paid';try{const plan=locked?salePlan(sale):salePlan({price:decimal(form.elements.price.value),date:form.elements.date.value,paymentMode:mode,entryCents:entry?decimal(form.elements.entryCents.value):0,entryCount:Number(form.elements.entryCount.value),entryFirstDue:form.elements.entryFirstDue.value,balanceDue:form.elements.balanceDue.value});$('#sale-plan-preview').textContent=plan.rows.map(i=>i.label+': '+money(i.cents)+' em '+brDate(i.due)).join(' · ');}catch{$('#sale-plan-preview').textContent='Preencha valor e condições para conferir as parcelas.';}};form.addEventListener('input',refresh);form.addEventListener('change',refresh);refresh();}
function saleReceiptForm(p,sale,installment){dialog('Registrar recebimento · '+esc(p.units.find(u=>u.id===sale.unitId).name),`<p class="callout wide">${esc(installment.label)} · Saldo: ${money(installment.cents-received(sale,installment.id))}. Confirme somente dinheiro já recebido.</p>`+number('cents','Valor recebido (R$)',val(installment.cents-received(sale,installment.id)),.01)+field('date','Data do recebimento',today(),'date',`required max="${today()}"`)+select('method','Forma do recebimento',choices(['PIX','Transferência','Dinheiro','Boleto','Financiamento liberado','Outro']),'PIX')+field('reference','Referência / comprovante (opcional)')+area('notes','Observações do recebimento (opcional)'),f=>save('sale.receipt',{projectId:p.id,id:sale.id,installmentId:installment.id,...Object.fromEntries(f),cents:decimal(f.get('cents'))}),'Confirmar recebimento');}
async function readSaleFile(file){if(file.size>CONTRACT_FILE_LIMIT)throw new Error('Cada documento deve ter até 1 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));return contractFileData({name:file.name,size:file.size,mime:file.type||(/\.pdf$/i.test(file.name)?'application/pdf':/\.png$/i.test(file.name)?'image/png':'image/jpeg'),data:btoa(binary)});}
function commercialForm(p,u){const c=u.commercial;dialog('Laudo e documentos · '+esc(u.name),check('hasAppraisal','A casa tem laudo de avaliação',!!c?.hasAppraisal)+number('appraisalCents','Valor do laudo (R$)',c?.hasAppraisal?val(c.appraisalCents):'',.01)+`<p class="fine wide">Documentos opcionais: PDF, JPG ou PNG de até 1 MB por arquivo. Ficam na conta e entram no backup financeiro.</p>`+Object.entries(SALE_DOCUMENTS).map(([kind,label])=>`<section class="wide sales-file-field"><label>${esc(label)}<input type="file" name="file-${kind}" accept="application/pdf,image/png,image/jpeg,.pdf,.png,.jpg,.jpeg"></label>${c?.documents[kind]?`<p class="fine">Arquivo atual: ${esc(c.documents[kind].name)}</p>`+check('remove-'+kind,'Remover '+esc(label.toLowerCase())):''}</section>`).join(''),async f=>{const documents={};for(const kind of Object.keys(SALE_DOCUMENTS)){const file=f.get('file-'+kind);if(file?.name){if(f.has('remove-'+kind))throw new Error('Escolha substituir ou remover o mesmo documento.');documents[kind]=await readSaleFile(file);}else if(f.has('remove-'+kind))documents[kind]=null;}return save('unit.commercial',{projectId:p.id,unitId:u.id,hasAppraisal:f.has('hasAppraisal'),appraisalCents:f.has('hasAppraisal')?decimal(f.get('appraisalCents')):0,documents});},'Salvar documentos / laudo');const form=$('#editor');const refresh=()=>form.elements.appraisalCents.disabled=!form.elements.hasAppraisal.checked;form.elements.hasAppraisal.onchange=refresh;refresh();}

function contractorExisting(p){const rows=p.expenses.filter(e=>!e.cancelled&&e.kind==='labor'&&!isContractor(e));dialog('Aproveitar custo já lançado',`<div class="wide"><p>Escolha o próprio contrato ou serviço que deseja acompanhar aqui. O valor e os pagamentos desse lançamento serão preservados, sem criar outro custo. Outros lançamentos não serão reunidos automaticamente.</p>${rows.map(e=>`<div class="payment-row"><div><strong>${esc(e.description)}</strong><small>${esc(e.supplier)} · ${money(e.total)} · Pago ${money(paid(e))}</small></div>${btn('contractor-edit','Usar este custo',e.id)}</div>`).join('')}</div>`,()=>{},'Fechar');}
function contractorForm(p,e){const sqm=e?e.uom==='m²':true;
 dialog(e?'Editar contrato do empreiteiro':'Cadastrar empreiteiro',`<p class="callout wide">${e?'Este é o mesmo lançamento de custo. Seus pagamentos serão preservados.':'O total contratado será incluído nos custos desta obra. Se o serviço já estiver lançado, use “Aproveitar custo já lançado”.'}</p>`+field('supplier','Nome do empreiteiro',e?.supplier||'','text','required maxlength="200"')+field('description','Identificação do serviço',e?.description||'Empreitada da obra','text','required maxlength="300"')+`<div class="contract-price">`+select('billing','Forma de contratação',[['sqm','Por metro quadrado'],['fixed','Valor fechado']],sqm?'sqm':'fixed')+`<div id="contract-sqm">`+number('areaQty','Metragem contratada (m²)',sqm&&e?val(e.qty,1000):val(sum(p.units,'area')),.001,'0.001')+number('rateCents','Mão de obra por m² (R$)',sqm&&e?val(e.unitCents):'',.01)+`<p class="fine">A metragem fica registrada no contrato. Alterar as casas depois não muda este valor.</p></div><div id="contract-fixed">`+number('fixedCents','Valor fechado do serviço (R$)',e?val(e.total):'',.01)+`</div><div class="callout">Total do serviço: <strong id="contract-total" aria-live="polite"></strong></div></div><label>O que o empreiteiro vai fazer?<textarea name="coverage" rows="9" required maxlength="2000" placeholder="Ex.: fundação, estrutura, alvenaria e cobertura. Detalhe o que está incluído e o que ficou fora.">${esc(e?.coverage||'')}</textarea></label>`+field('date','Data da contratação',e?.date||today(),'date','required')+select('stageId','Etapa do contrato (opcional)',expenseStageOptions(p),p.stages.find(st=>st.id===e?.stageId)?.unassigned?'':e?.stageId||'')+area('notes','Condições, prazos e observações (opcional)',e?.notes||'')+`<label class="wide">Anexar contrato (opcional)<input type="file" name="contractUpload" accept="application/pdf,image/png,image/jpeg,.pdf,.png,.jpg,.jpeg"><small>PDF, JPG ou PNG de até 1 MB. Salvo neste navegador e incluído no Backup dos custos.</small></label>${e?.contractFile?`<p class="fine wide">Anexo atual: ${esc(e.contractFile.name)}. Escolher outro arquivo substitui o atual.</p>`+check('removeFile','Remover o anexo atual'):''}`,async f=>{
 const billing=f.get('billing'),data={projectId:p.id,...(e?{id:e.id}:{}),supplier:f.get('supplier'),description:f.get('description'),billing,date:f.get('date'),due:e?.due||f.get('date'),stageId:f.get('stageId'),coverage:f.get('coverage'),notes:f.get('notes'),reference:e?.reference||'',...(billing==='sqm'?{areaQty:decimal(f.get('areaQty'),3),rateCents:decimal(f.get('rateCents'))}:{fixedCents:decimal(f.get('fixedCents'))})};
 const file=f.get('contractUpload');if(file?.size){if(f.has('removeFile'))throw new Error('Escolha substituir ou remover o anexo, não ambos.');if(file.size>CONTRACT_FILE_LIMIT)throw new Error('Use um contrato de até 1 MB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));data.contractFile=contractFileData({name:file.name,size:file.size,mime:file.type||(/\.pdf$/i.test(file.name)?'application/pdf':/\.png$/i.test(file.name)?'image/png':'image/jpeg'),data:btoa(binary)});}else if(f.has('removeFile'))data.contractFile=null;
 return save('contractor.save',data);
 },'Salvar contrato');
 const form=$('#editor'),refresh=()=>{const sqm=form.elements.billing.value==='sqm';$('#contract-sqm').hidden=!sqm;$('#contract-fixed').hidden=sqm;for(const name of ['areaQty','rateCents'])form.elements[name].disabled=!sqm;form.elements.fixedCents.disabled=sqm;try{$('#contract-total').textContent=money(sqm?amount(decimal(form.elements.rateCents.value),decimal(form.elements.areaQty.value,3)):decimal(form.elements.fixedCents.value));}catch{$('#contract-total').textContent='Preencha os valores';}};form.addEventListener('input',refresh);form.addEventListener('change',refresh);refresh();
}

function paymentForm(p,e){dialog(isContractor(e)?'Registrar vale / pagamento':'Registrar pagamento',`<div class="callout wide"><strong>${esc(e.supplier||e.description)}</strong><br>Saldo contratado: ${money(e.total-paid(e))}. Este registro abate o saldo e não gera outro custo.</div>`+number('cents','Valor pago (R$)',isContractor(e)?'':val(e.total-paid(e)),.01)+field('date','Data do pagamento',today(),'date',`required max="${today()}"`)+select('stageId','Referente à etapa (opcional)',expenseStageOptions(p),'')+select('method','Forma de pagamento',choices(['PIX','Transferência','Boleto','Dinheiro','Cartão','Outro']),'PIX')+field('reference','Comprovante / referência','')+area('notes','Observação do vale / pagamento (opcional)')+'<p class="fine wide">Informe uma etapa quando o pagamento estiver ligado a uma fase concluída. Nenhuma transferência bancária é realizada.</p>',f=>save('payment.add',{...Object.fromEntries(f),projectId:p.id,id:e.id,cents:decimal(f.get('cents'))}),'Confirmar registro');}
function stageForm(p,st){dialog(st?'Atualizar etapa da obra':'Criar etapa da obra',field('name','Nome da etapa',st?.name||'','text','required maxlength="100"')+number('progress','Percentual concluído (%)',st?.progress||0,0,'1')+check('trackProgress','Esta etapa se aplica à obra e entra no avanço total',st?isProgressStage(st):true)+`<p class="callout wide">0% significa não iniciada; 100%, concluída. Desmarque uma etapa que não se aplica para deixá-la fora da média da obra.</p>`,f=>save('stage.save',{projectId:p.id,...(st?{id:st.id}:{}),name:f.get('name'),budget:st?.budget||0,progress:Number(f.get('progress')),trackProgress:f.has('trackProgress')}),'Salvar etapa');$('#editor').elements.progress.max='100';}
function stageBudgetForm(p,st){dialog('Orçamento da etapa',`<p class="callout wide">${esc(st.name)}. Informe o custo final esperado, incluindo o que já foi contratado.</p>`+number('budget','Orçamento total da etapa (R$)',val(st.budget)),f=>save('stage.save',{projectId:p.id,id:st.id,name:st.name,budget:decimal(f.get('budget')),progress:st.progress}),'Salvar orçamento');}

function comparableForm(c){const p=current(),referenceUnit=p.units.find(u=>u.id===marketFilter.unitId)||p.units[0];dialog(c?'Conferir referência de mercado':'Registrar anúncio conferido',field('title','Título da referência',c?.title||'','text','required')+field('source','Portal / imobiliária / referência',c?.source||'','text','required')+field('url','URL HTTPS do anúncio',c?.url||'','url','required')+field('date','Data em que o anúncio foi consultado',c?.date||today(),'date',`required max="${today()}"`)+field('neighborhood','Bairro',c?.neighborhood||p.neighborhood,'text','required list="neighborhoods"')+select('zone','Zona confirmada no anúncio',choices(['Zona 1','Zona 2','Zona 3','Não informada']),c?.zone||'Não informada')+select('type','Tipo',[['condominium','Sobrado em condomínio'],['individual','Sobrado individual']],c?.type||p.type)+select('condition','Condição',[['new','Novo'],['used','Usado / reformado'],['unknown','Não informada']],c?.condition||'unknown')+number('bedrooms','Dormitórios',c?.bedrooms??referenceUnit.bedrooms??p.bedrooms,1,'1')+number('area','Área privativa / construída do sobrado (m²)',c?val(c.area):val(referenceUnit.area),.01)+number('price','Preço anunciado (R$)',c?val(c.price):0,.01)+area('notes','Condição, padrão, distância da praia e observações',c?.notes||'')+`<p class="fine wide">Use a área da unidade, não a área total do terreno. Marque zona não informada quando a fonte não confirmar. Preços e disponibilidade precisam ser conferidos novamente com o anunciante.</p>`,f=>{const d=Object.fromEntries(f);d.area=decimal(d.area);d.price=decimal(d.price);d.bedrooms=Number(d.bedrooms);if(d.date>today())throw new Error('A consulta não pode ter data futura.');return save('comparable.save',{...d,...(c?{id:c.id}:{})});});}
function report(p){const t=totals(p);dialog('Relatório completo da obra',`<div class="wide report" id="print-content"><div class="report-head"><span class="eyebrow">SOLUÇÃO SOBRADOS · RELATÓRIO DE CUSTOS</span><h2>${esc(p.name)}</h2><p>${esc(p.neighborhood)} · ${esc(p.zone)} · ${p.units.length} unidades · ${fmt(t.area)} m² · Emitido em ${brDate(today())}</p>${tag(p.status==='closed'?'Obra encerrada · custo registrado':'Obra em andamento · custo ainda previsto','blue')}</div>${projectionNotice(p)}<div class="metrics three">${metric('Contratado / incorrido',money(t.contracted),'Pago '+money(t.paid))}${metric('Custo final previsto',money(t.forecast),'Inclui reserva '+money(t.reserve))}${metric('Lucro previsto',money(t.profit),'Venda estimada '+money(t.revenue))}</div><h3>Todos os custos, inclusive os extras</h3>${costTable(p,p.expenses.filter(e=>!e.cancelled),false)}<h3>Detalhes e justificativas</h3>${p.expenses.filter(e=>!e.cancelled&&(e.notes||e.coverage)).map(e=>`<p><strong>${esc(e.description)}:</strong> ${esc(e.notes)} ${e.coverage?'Escopo: '+esc(e.coverage):''}</p>`).join('')||'<p>Sem observações adicionais.</p>'}<h3>Resultado por unidade</h3><div class="table-scroll"><table><thead><tr><th>Unidade</th><th>Contratado</th><th>Pago alocado</th><th>Previsão final</th><th>Venda estimada</th><th>Lucro previsto</th></tr></thead><tbody>${t.units.map(u=>`<tr><td>${esc(u.name)}</td><td>${money(u.contracted)}</td><td>${money(u.paid)}</td><td>${money(u.forecast)}</td><td>${money(u.sale)}</td><td>${money(u.profit)}</td></tr>`).join('')}</tbody></table></div><h3>Pagamentos registrados</h3><div class="table-scroll"><table><thead><tr><th>Data</th><th>Custo</th><th>Valor</th><th>Forma / referência</th><th>Etapa / observação</th><th>Situação</th></tr></thead><tbody>${p.expenses.flatMap(e=>e.payments.map(pay=>`<tr><td>${brDate(pay.date)}</td><td>${esc(e.description)}</td><td>${money(pay.cents)}</td><td>${esc(pay.method)} · ${esc(pay.reference)}</td><td>${esc(paymentStage(p,pay))} · ${esc(pay.notes||'')}</td><td>${pay.reversed?'Estornado: '+esc(pay.reversed):'Confirmado'}</td></tr>`)).join('')}</tbody></table></div><p class="fine">Margem prevista: ${pct(t.margin)}. Despesas de venda ainda previstas: ${money(t.selling)}. Comissões já registradas nos custos são descontadas da previsão de ${fmt(p.sellingBps/100)}%. Valores vendidos são contratos; confira o dinheiro recebido em Entradas / recebidos. Projeção depende da completude dos custos e orçamentos. Custos comuns são rateados; pagamentos e consumo não duplicam o valor contratado.</p></div><div class="actions wide no-print">${btn('print','Imprimir / salvar PDF')}${btn('export-costs','Exportar custos CSV')}${btn('payments-export','Exportar pagamentos CSV')}</div>`,()=>{},'Fechar');$('#dialog').classList.add('report-dialog');$('#dialog').addEventListener('close',()=>$('#dialog').classList.remove('report-dialog'),{once:true});}
function trashList(){const rows=state.projects.filter(p=>p.trashedAt);dialog('Lixeira de empreendimentos',`<div class="wide"><p>Os custos, pagamentos e unidades estão preservados. Restaurar devolve o empreendimento à lista principal.</p>${rows.length?rows.map(p=>`<div class="payment-row"><div><strong>${esc(p.name)}</strong><small>Movido em ${brDate(p.trashedAt)} · ${p.units.length} unidade(s) · ${p.expenses.filter(e=>!e.cancelled).length} custo(s)</small></div>${btn('project-restore','Restaurar empreendimento',p.id)}</div>`).join(''):'<p>A lixeira está vazia.</p>'}<p class="fine">Os itens da lixeira também entram no backup desta base. Esta ação não remove documentos ou diários online nem revoga links compartilhados.</p></div>`,()=>{},'Fechar');}
async function act(action,id){const p=current(),e=p?.expenses.find(x=>x.id===id);
  if(action==='logout'){await accountApi('/logout',{});mode='online';await boot();}
  else if(action==='migrate-local'){migrationForm();}
  else if(action==='menu-open'){setNavigation(true);}
  else if(action==='menu-close'){setNavigation(false);}
  else if(action==='nav'){page=id;render();$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
  else if(action==='overview'){page='overview';render();$('#main').focus({preventScroll:true});}
  else if(action==='cost-filter-reset'){costFilter={stage:'',kind:'',search:'',unit:''};render();}
  else if(action==='refresh'){await load();render();toast('Dados atualizados.');}
  else if(action==='workspace'){mode=mode==='demo'?'online':'demo';selected='';page='overview';await load();render();}
  else if(action==='backup')download(`solucao-sobrados-${mode}-${today()}.json`,JSON.stringify(state,null,2));
  else if(action==='import')$('#restore').click();
  else if(action==='project-trash-list')trashList();
  else if(action==='project-trash'){dialog('Excluir empreendimento',`<div class="callout wide"><strong>${esc(p.name)}</strong><br>Este empreendimento e seus ${p.expenses.filter(e=>!e.cancelled).length} custo(s) sairão da lista principal e dos comparativos. Você poderá recuperar tudo pela Lixeira.<br>Diário, documentos, agenda online e links compartilhados continuam disponíveis.</div>`+field('confirmName','Digite o nome do empreendimento para confirmar','','text','required autocomplete="off"')+'<p class="fine wide">Esta ação vale apenas para a base deste navegador. Nada será apagado definitivamente.</p>',f=>save('project.trash',{projectId:p.id,confirmName:f.get('confirmName')}),'Mover para a lixeira');}
  else if(action==='project-restore'){await save('project.restore',{projectId:id});$('#dialog').close();}
  else if(action==='project-new')projectForm();
  else if(action==='project-edit')projectForm(p);
  else if(action==='unit-edit'||action==='unit-add')unitForm(p,p.units.find(u=>u.id===id));
  else if(action==='expense-quick')quickExpenseForm(p,id);
  else if(action==='sale-new')saleForm(p,p.units.find(u=>u.id===id));
  else if(action==='sale-edit'){const sale=p.sales.find(s=>s.id===id);saleForm(p,p.units.find(u=>u.id===sale.unitId),sale);}
  else if(action==='sale-detail')saleDetail(p,p.sales.find(s=>s.id===id));
  else if(action==='unit-commercial')commercialForm(p,p.units.find(u=>u.id===id));
  else if(action==='sale-document'){const [uid,kind]=id.split('|'),file=contractFileData(p.units.find(u=>u.id===uid).commercial.documents[kind]);download(file.name,Uint8Array.from(atob(file.data),c=>c.charCodeAt(0)),file.mime);}
  else if(action==='sale-receipt'){const [sid,iid]=id.split('|'),sale=p.sales.find(s=>s.id===sid);saleReceiptForm(p,sale,sale.installments.find(i=>i.id===iid));}
  else if(action==='sale-receipt-reverse'){const [sid,rid]=id.split('|');dialog('Estornar registro de recebimento',area('reason','Motivo do estorno')+'<p class="fine wide">O histórico será preservado e o valor voltará a receber. Este registro não realiza devolução bancária.</p>',f=>save('sale.receipt.reverse',{projectId:p.id,id:sid,receiptId:rid,reason:f.get('reason')}),'Confirmar estorno');}
  else if(action==='sale-cancel')dialog('Cancelar venda',area('reason','Motivo do cancelamento')+'<p class="callout wide">A casa voltará a disponível. Estorne antes os recebimentos e o pagamento da comissão. O histórico e os documentos serão preservados.</p>',f=>save('sale.cancel',{projectId:p.id,id,reason:f.get('reason')}),'Cancelar venda');
  else if(action==='receipts-export')download('recebimentos-'+p.id+'.csv',csv([['Empreendimento','Casa','Comprador','Parcela','Data','Valor R$','Forma','Referência','Observação','Situação'],...(p.sales||[]).flatMap(s=>s.receipts.map(r=>[p.name,p.units.find(u=>u.id===s.unitId).name,s.buyer,s.installments.find(i=>i.id===r.installmentId).label,r.date,(r.cents/100).toFixed(2),r.method,r.reference,r.notes,r.reversed?'Estornado: '+r.reversed:'Confirmado']))]),'text/csv;charset=utf-8');
  else if(action==='contractor-new'||action==='contractor-edit')contractorForm(p,e);
  else if(action==='contractor-existing')contractorExisting(p);
  else if(action==='contractor-file'){const file=contractFileData(e.contractFile);download(file.name,Uint8Array.from(atob(file.data),c=>c.charCodeAt(0)),file.mime);}
  else if(action==='expense-new'||action==='expense-edit'){if(e?.saleId){const sale=p.sales.find(s=>s.id===e.saleId);saleForm(p,p.units.find(u=>u.id===sale.unitId),sale);}else if(e&&isContractor(e))contractorForm(p,e);else expenseForm(p,e);}
  else if(action==='expense-detail')expenseDetail(p,e);
  else if(action==='construction-classify')constructionForm(p,e);
  else if(action==='payment')paymentForm(p,e);
  else if(action==='payment-reverse'){const [eid,payid]=id.split('|');dialog('Estornar registro de pagamento',area('reason','Motivo do estorno')+'<p class="fine wide">O pagamento ficará no histórico e seu valor voltará ao saldo a pagar. Não há estorno bancário automático.</p>',f=>save('payment.reverse',{projectId:p.id,id:eid,paymentId:payid,reason:f.get('reason')}),'Confirmar estorno do registro');}
  else if(action==='expense-cancel')dialog('Cancelar lançamento',area('reason','Justificativa do cancelamento'),f=>save('expense.cancel',{projectId:p.id,id,reason:f.get('reason')}),'Cancelar lançamento');
  else if(action==='stage-new'||action==='stage-edit')stageForm(p,p.stages.find(x=>x.id===id));
  else if(action==='stage-budget')stageBudgetForm(p,p.stages.find(x=>x.id===id));
  else if(action==='material-use')dialog('Registrar material utilizado',`<div class="callout wide">${esc(e.description)} · disponível: ${fmt((e.qty-used(e))/1000)} ${esc(e.uom)}. Este registro não gera custo adicional.</div>`+number('qty',`Quantidade utilizada (${esc(e.uom)})`,1,.001,'0.001')+field('date','Data do consumo',today(),'date',`required max="${today()}"`)+select('stageId','Etapa onde foi utilizado',p.stages.map(st=>[st.id,st.name]),e.stageId)+select('unitId','Local de uso',[['','Uso comum / todas'],...p.units.map(u=>[u.id,u.name])])+area('notes','Observações'),f=>save('material.use',{...Object.fromEntries(f),projectId:p.id,id,qty:decimal(f.get('qty'),3)}));
  else if(action==='project-close')dialog('Conferir e encerrar a obra',`<div class="callout wide">Inclua todos os custos, confira os extras e quite os saldos registrados. Ao encerrar, o custo final passa a ser o total dos lançamentos, sem orçamento restante nem reserva. Os valores de venda continuam estimados.</div>`+field('date','Data do encerramento',today(),'date',`required max="${today()}"`)+area('reason','Conferência final / observações'),f=>save('project.close',{...Object.fromEntries(f),projectId:p.id}),'Encerrar obra');
  else if(action==='project-reopen')dialog('Reabrir empreendimento',area('reason','Justificativa para reabrir'),f=>save('project.reopen',{projectId:p.id,reason:f.get('reason')}),'Reabrir');
  else if(action==='comparable-new'||action==='comparable-edit')comparableForm(state.comparables.find(c=>c.id===id));
  else if(action==='export-costs')download('custos-'+p.id+'.csv',costReport(p),'text/csv;charset=utf-8');
  else if(action==='payments-export')download('pagamentos-'+p.id+'.csv',csv([['Empreendimento','Custo','Data','Valor R$','Forma','Referência','Etapa','Observação','Situação'],...p.expenses.flatMap(e=>e.payments.map(pay=>[p.name,e.description,pay.date,(pay.cents/100).toFixed(2),pay.method,pay.reference,paymentStage(p,pay),pay.notes||'',pay.reversed?'Estornado: '+pay.reversed:'Confirmado']))]),'text/csv;charset=utf-8');
  else if(action==='history-export')download('comparativo-'+years.a+'-'+years.b+'.csv',csv([['Item','Medida','Natureza',years.a+' R$',years.b+' R$','Variação nominal %'],...history(state,years.a,years.b).map(r=>[r.name,r.uom,KINDS[r.kind],r.priceA===null?'':(r.priceA/100).toFixed(2),r.priceB===null?'':(r.priceB/100).toFixed(2),r.change===null?'':(r.change*100).toFixed(2)])]),'text/csv;charset=utf-8');
  else if(action==='report')report(p);
  else if(action==='print')window.print();
}
$('#dialog').onclick=async e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();try{await act(el.dataset.action,el.dataset.id);}catch(err){toast(err.message,true);}}};
$('#restore').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(actor?.role!=='admin')throw new Error('Somente o administrador pode restaurar a base.');if(file.size>12*1024*1024)throw new Error('Backup maior que 12 MB.');const parsed=validate(JSON.parse(await file.text())),revision=state.revision;dialog('Restaurar base financeira da conta',`<p class="callout wide">${parsed.projects.length} empreendimento(s) substituirão a base financeira de ${esc(organizationName)}. Chamados de manutenção permanecem preservados.</p>`+field('confirm','Digite RESTAURAR para confirmar','','text','required'),async f=>{if(f.get('confirm')!=='RESTAURAR')throw new Error('Digite RESTAURAR para confirmar.');download('antes-da-restauracao-'+today()+'.json',JSON.stringify(state));await accountApi('/restore',{revision,financial:parsed});mode='online';await load();render();toast('Base restaurada na conta.');},'Restaurar');}catch(error){toast(error.message,true);}};
window.addEventListener('hashchange',()=>boot());
